CREATE OR REPLACE FUNCTION ops.require_pdf_stage_owner(p_task bigint,p_attempt bigint,p_holder
 text)
RETURNS ops.run LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $stage$
DECLARE job ops.task; run ops.run;
BEGIN
 IF p_task IS NULL OR p_attempt IS NULL OR p_holder IS NULL OR p_holder='' THEN
 RAISE EXCEPTION 'stale private PDF build owner' USING ERRCODE='P0004'; END IF;
 SELECT r.* INTO STRICT run FROM ops.run r JOIN ops.task t ON t.run_id=r.id WHERE t.id=p_task
 FOR SHARE OF r;
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task AND run_id=run.id FOR UPDATE;
 IF job.attempt IS DISTINCT FROM p_attempt OR job.claimed_by IS DISTINCT FROM p_holder
 OR job.status<>'running'
 OR job.lease_until IS NULL OR job.lease_until<=clock_timestamp() OR run.sealed OR run.status
 NOT IN ('created','running') THEN
  RAISE EXCEPTION 'stale private PDF build owner' USING ERRCODE='P0004'; END IF;
 RETURN run;
END $stage$;
REVOKE ALL ON FUNCTION ops.require_pdf_stage_owner(bigint,bigint,text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.begin_pdf_build(p_task bigint,p_attempt bigint,p_holder text,
 p_source text,p_recipe text,p_schema text,p_key text)
RETURNS SETOF ops.pdf_stage_build LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,
 pg_temp AS $stage$
DECLARE run ops.run; build ops.pdf_stage_build; id text;
BEGIN
 run:=ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(run.release_id,'begin_pdf_build');
 IF p_source IS NULL OR p_recipe IS NULL OR p_schema IS DISTINCT FROM '3123788cfea7ddd282a4ec8fdeafee98d106ec2863d6722bbde4fc2f3f2e1bc1'
 OR p_key IS NULL OR p_key=''
 OR octet_length(p_key)>1024 OR NOT
 EXISTS(SELECT FROM ops.source_build s WHERE s.task_id=p_task
 AND s.release_id=run.release_id AND s.artifact_digest=p_source AND (s.recipe_digest=p_recipe OR EXISTS(SELECT FROM ops.pdf_stage_recipe sr WHERE sr.task_id=p_task AND sr.source_digest=p_source AND sr.root_recipe_digest=s.recipe_digest AND sr.stage_recipe_digest=p_recipe)))
 OR NOT EXISTS(SELECT FROM kb.document d JOIN ops.task t ON t.id=p_task WHERE
 d.project_id=run.project_id
 AND d.content_hash=p_source AND ((t.unit_type='document' AND d.id=t.unit_id) OR
 (t.unit_type='source_view' AND EXISTS(
 SELECT FROM kb.source_view v JOIN ops.run_source_view s ON s.source_view_id=v.id WHERE
 v.id=t.unit_id AND s.run_id=run.id AND v.document_id=d.id)))) THEN
 RAISE EXCEPTION 'private PDF build source custody differs' USING ERRCODE='23514'; END IF;
 id:=encode(sha256(convert_to(jsonb_build_array(p_task,p_source,p_recipe,p_schema,p_key)::text,
 'UTF8')),'hex');
 INSERT INTO ops.pdf_stage_build VALUES(id,p_task,run.id,run.release_id,p_source,p_recipe,
 p_schema,p_key,p_attempt,p_holder,'open')
 ON CONFLICT(task_id,replay_key) DO NOTHING;
 SELECT * INTO STRICT build FROM ops.pdf_stage_build WHERE task_id=p_task AND replay_key=p_key;
 IF build.build_id IS DISTINCT FROM id OR build.attempt IS DISTINCT FROM p_attempt
 OR build.holder IS DISTINCT FROM p_holder OR
 build.state<>'open' THEN
 RAISE EXCEPTION 'private PDF build replay differs or requires explicit resume' USING
 ERRCODE='23514'; END IF;
 RETURN NEXT build;
END $stage$;
CREATE OR REPLACE FUNCTION ops.require_pdf_build(p_build text,p_task bigint,p_attempt bigint,
 p_holder text)
RETURNS ops.pdf_stage_build LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,
 pg_temp AS $stage$
DECLARE run ops.run; build ops.pdf_stage_build;
BEGIN
 run:=ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 IF p_build IS NULL THEN RAISE EXCEPTION 'private PDF build is not owned/open'
 USING ERRCODE='P0004'; END IF;
 SELECT * INTO STRICT build FROM ops.pdf_stage_build WHERE build_id=p_build AND task_id=p_task
 FOR UPDATE;
 IF build.release_id IS DISTINCT FROM run.release_id OR build.attempt IS DISTINCT FROM p_attempt
 OR build.holder IS DISTINCT FROM p_holder OR
 build.state<>'open' THEN
 RAISE EXCEPTION 'private PDF build is not owned/open' USING ERRCODE='P0004'; END IF;
 RETURN build;
END $stage$;
REVOKE ALL ON FUNCTION ops.require_pdf_build(text,bigint,bigint,text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.require_pdf_stage_scratch(p_name text,p_relation regclass)
RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog,pg_temp AS $stage$
DECLARE scratch oid:=to_regclass('pg_temp.'||p_name);
BEGIN
 IF scratch IS NULL OR NOT EXISTS(SELECT FROM pg_class WHERE oid=scratch
 AND relowner='corpus_sem_publisher'::regrole AND relnamespace=pg_my_temp_schema()
 AND relkind='r' AND relpersistence='t' AND NOT relrowsecurity) OR
 EXISTS(SELECT FROM pg_trigger WHERE tgrelid=scratch) OR
 EXISTS(SELECT FROM pg_rewrite WHERE ev_class=scratch) OR
 EXISTS(SELECT FROM pg_inherits WHERE inhrelid=scratch OR inhparent=scratch) OR
 EXISTS(SELECT FROM pg_attrdef WHERE adrelid=scratch) OR
 EXISTS(SELECT FROM pg_index WHERE indrelid=scratch) OR
 EXISTS(SELECT FROM pg_constraint WHERE conrelid=scratch
 AND (contype NOT IN ('c','n') OR NOT convalidated)) THEN
 RAISE EXCEPTION 'untrusted private PDF scratch' USING ERRCODE='23514'; END IF;
 IF ARRAY(SELECT ROW(attnum,attname,atttypid,atttypmod,attnotnull,attgenerated,attidentity)::text
 FROM pg_attribute WHERE attrelid=scratch AND attnum>0 AND NOT attisdropped ORDER BY attnum)
 IS DISTINCT FROM
 ARRAY(SELECT ROW(attnum,attname,atttypid,atttypmod,attnotnull,attgenerated,attidentity)::text
 FROM pg_attribute WHERE attrelid=p_relation AND attnum>0 AND NOT attisdropped ORDER BY attnum)
 OR ARRAY(SELECT pg_get_constraintdef(oid,true) FROM pg_constraint
 WHERE conrelid=scratch AND contype='c' ORDER BY 1) IS DISTINCT FROM
 ARRAY(SELECT pg_get_constraintdef(oid,true) FROM pg_constraint
 WHERE conrelid=p_relation AND contype='c' ORDER BY 1) THEN
 RAISE EXCEPTION 'private PDF scratch schema differs' USING ERRCODE='23514'; END IF;
END $stage$;
REVOKE ALL ON FUNCTION ops.require_pdf_stage_scratch(text,regclass) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.prepare_pdf_stage(p_build text,p_task bigint,p_attempt bigint,
 p_holder text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $stage$
DECLARE build ops.pdf_stage_build;
BEGIN
 build:=ops.require_pdf_build(p_build,p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(build.release_id,'adopt_pdf_batch');
IF to_regclass('pg_temp.ps_pdf_stage_document') IS NULL THEN CREATE TEMP TABLE ps_pdf_stage_document (LIKE ops.pdf_stage_document INCLUDING CONSTRAINTS) ON COMMIT DROP; ELSE PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_document','ops.pdf_stage_document'::regclass); END IF; TRUNCATE pg_temp.ps_pdf_stage_document;
GRANT SELECT,INSERT ON pg_temp.ps_pdf_stage_document TO corpus_sem_writer;
IF to_regclass('pg_temp.ps_pdf_stage_native') IS NULL THEN CREATE TEMP TABLE ps_pdf_stage_native (LIKE ops.pdf_stage_native INCLUDING CONSTRAINTS) ON COMMIT DROP; ELSE PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_native','ops.pdf_stage_native'::regclass); END IF; TRUNCATE pg_temp.ps_pdf_stage_native;
GRANT SELECT,INSERT ON pg_temp.ps_pdf_stage_native TO corpus_sem_writer;
IF to_regclass('pg_temp.ps_pdf_stage_membership') IS NULL THEN CREATE TEMP TABLE ps_pdf_stage_membership (LIKE ops.pdf_stage_membership INCLUDING CONSTRAINTS) ON COMMIT DROP; ELSE PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_membership','ops.pdf_stage_membership'::regclass); END IF; TRUNCATE pg_temp.ps_pdf_stage_membership;
GRANT SELECT,INSERT ON pg_temp.ps_pdf_stage_membership TO corpus_sem_writer;
IF to_regclass('pg_temp.ps_pdf_stage_reference') IS NULL THEN CREATE TEMP TABLE ps_pdf_stage_reference (LIKE ops.pdf_stage_reference INCLUDING CONSTRAINTS) ON COMMIT DROP; ELSE PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_reference','ops.pdf_stage_reference'::regclass); END IF; TRUNCATE pg_temp.ps_pdf_stage_reference;
GRANT SELECT,INSERT ON pg_temp.ps_pdf_stage_reference TO corpus_sem_writer;
IF to_regclass('pg_temp.ps_pdf_stage_artifact_stream') IS NULL THEN CREATE TEMP TABLE ps_pdf_stage_artifact_stream (LIKE ops.pdf_stage_artifact_stream INCLUDING CONSTRAINTS) ON COMMIT DROP; ELSE PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_artifact_stream','ops.pdf_stage_artifact_stream'::regclass); END IF; TRUNCATE pg_temp.ps_pdf_stage_artifact_stream;
GRANT SELECT,INSERT ON pg_temp.ps_pdf_stage_artifact_stream TO corpus_sem_writer;
IF to_regclass('pg_temp.ps_pdf_stage_artifact_part') IS NULL THEN CREATE TEMP TABLE ps_pdf_stage_artifact_part (LIKE ops.pdf_stage_artifact_part INCLUDING CONSTRAINTS) ON COMMIT DROP; ELSE PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_artifact_part','ops.pdf_stage_artifact_part'::regclass); END IF; TRUNCATE pg_temp.ps_pdf_stage_artifact_part;
GRANT SELECT,INSERT ON pg_temp.ps_pdf_stage_artifact_part TO corpus_sem_writer;
END $stage$;

CREATE OR REPLACE FUNCTION ops.adopt_pdf_batch(p_build text,p_task bigint,p_attempt bigint,
 p_holder text,p_key text)
RETURNS SETOF ops.pdf_stage_receipt LANGUAGE plpgsql SECURITY DEFINER SET
 search_path=pg_catalog,pg_temp AS $stage$
DECLARE build ops.pdf_stage_build; receipt ops.pdf_stage_receipt; n bigint; bytes bigint;
 total bigint:=0; total_bytes bigint:=0; hashes text:=''; digest text;
BEGIN
 build:=ops.require_pdf_build(p_build,p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(build.release_id,'adopt_pdf_batch');
 IF p_key IS NULL OR p_key='' OR octet_length(p_key)>1024 THEN
 RAISE EXCEPTION 'invalid private replay key'
 USING ERRCODE='23514'; END IF;

 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_artifact_part','ops.pdf_stage_artifact_part'::regclass);
 SELECT count(*),COALESCE(sum(octet_length(to_jsonb(s)::text)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_artifact_part s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
 'private PDF upload profile exceeded' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_artifact_part WHERE product_id IS DISTINCT FROM p_build
 OR revision_id IS DISTINCT FROM p_build)
 OR EXISTS(SELECT FROM pg_temp.ps_pdf_stage_artifact_part GROUP BY product_id,revision_id,stream_id,ordinal HAVING count(*)>1) THEN
 RAISE EXCEPTION 'private PDF upload ownership or duplicate key differs' USING ERRCODE='23514';
 END IF;
 SELECT hashes||'ops.pdf_stage_artifact_part:'||encode(sha256(convert_to(
 COALESCE(string_agg(to_jsonb(s)::text,E'\n' ORDER BY product_id,revision_id,stream_id,ordinal),''),'UTF8')),'hex')
 INTO hashes FROM pg_temp.ps_pdf_stage_artifact_part s;

 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_artifact_stream','ops.pdf_stage_artifact_stream'::regclass);
 SELECT count(*),COALESCE(sum(octet_length(to_jsonb(s)::text)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_artifact_stream s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
 'private PDF upload profile exceeded' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_artifact_stream WHERE product_id IS DISTINCT FROM p_build
 OR revision_id IS DISTINCT FROM p_build)
 OR EXISTS(SELECT FROM pg_temp.ps_pdf_stage_artifact_stream GROUP BY product_id,revision_id,stream_id HAVING count(*)>1) THEN
 RAISE EXCEPTION 'private PDF upload ownership or duplicate key differs' USING ERRCODE='23514';
 END IF;
 SELECT hashes||'ops.pdf_stage_artifact_stream:'||encode(sha256(convert_to(
 COALESCE(string_agg(to_jsonb(s)::text,E'\n' ORDER BY product_id,revision_id,stream_id),''),'UTF8')),'hex')
 INTO hashes FROM pg_temp.ps_pdf_stage_artifact_stream s;

 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_document','ops.pdf_stage_document'::regclass);
 SELECT count(*),COALESCE(sum(octet_length(to_jsonb(s)::text)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_document s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
 'private PDF upload profile exceeded' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_document WHERE product_id IS DISTINCT FROM p_build
 OR revision_id IS DISTINCT FROM p_build)
 OR EXISTS(SELECT FROM pg_temp.ps_pdf_stage_document GROUP BY product_id,revision_id HAVING count(*)>1) THEN
 RAISE EXCEPTION 'private PDF upload ownership or duplicate key differs' USING ERRCODE='23514';
 END IF;
 SELECT hashes||'ops.pdf_stage_document:'||encode(sha256(convert_to(
 COALESCE(string_agg(to_jsonb(s)::text,E'\n' ORDER BY product_id,revision_id),''),'UTF8')),'hex')
 INTO hashes FROM pg_temp.ps_pdf_stage_document s;

 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_membership','ops.pdf_stage_membership'::regclass);
 SELECT count(*),COALESCE(sum(octet_length(to_jsonb(s)::text)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_membership s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
 'private PDF upload profile exceeded' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_membership WHERE product_id IS DISTINCT FROM p_build
 OR revision_id IS DISTINCT FROM p_build)
 OR EXISTS(SELECT FROM pg_temp.ps_pdf_stage_membership GROUP BY product_id,revision_id,parent_id,field_name,ordinal HAVING count(*)>1) THEN
 RAISE EXCEPTION 'private PDF upload ownership or duplicate key differs' USING ERRCODE='23514';
 END IF;
 SELECT hashes||'ops.pdf_stage_membership:'||encode(sha256(convert_to(
 COALESCE(string_agg(to_jsonb(s)::text,E'\n' ORDER BY product_id,revision_id,parent_id,field_name,ordinal),''),'UTF8')),'hex')
 INTO hashes FROM pg_temp.ps_pdf_stage_membership s;

 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_native','ops.pdf_stage_native'::regclass);
 SELECT count(*),COALESCE(sum(octet_length(to_jsonb(s)::text)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_native s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
 'private PDF upload profile exceeded' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_native WHERE product_id IS DISTINCT FROM p_build
 OR revision_id IS DISTINCT FROM p_build)
 OR EXISTS(SELECT FROM pg_temp.ps_pdf_stage_native GROUP BY product_id,revision_id,record_id HAVING count(*)>1) THEN
 RAISE EXCEPTION 'private PDF upload ownership or duplicate key differs' USING ERRCODE='23514';
 END IF;
 SELECT hashes||'ops.pdf_stage_native:'||encode(sha256(convert_to(
 COALESCE(string_agg(to_jsonb(s)::text,E'\n' ORDER BY product_id,revision_id,record_id),''),'UTF8')),'hex')
 INTO hashes FROM pg_temp.ps_pdf_stage_native s;

 PERFORM ops.require_pdf_stage_scratch('ps_pdf_stage_reference','ops.pdf_stage_reference'::regclass);
 SELECT count(*),COALESCE(sum(octet_length(to_jsonb(s)::text)),0) INTO n,bytes FROM pg_temp.ps_pdf_stage_reference s;
 total:=total+n; total_bytes:=total_bytes+bytes;
 IF total>65536 OR total_bytes>8388608 THEN RAISE EXCEPTION
 'private PDF upload profile exceeded' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_reference WHERE product_id IS DISTINCT FROM p_build
 OR revision_id IS DISTINCT FROM p_build)
 OR EXISTS(SELECT FROM pg_temp.ps_pdf_stage_reference GROUP BY product_id,revision_id,reference_id HAVING count(*)>1) THEN
 RAISE EXCEPTION 'private PDF upload ownership or duplicate key differs' USING ERRCODE='23514';
 END IF;
 SELECT hashes||'ops.pdf_stage_reference:'||encode(sha256(convert_to(
 COALESCE(string_agg(to_jsonb(s)::text,E'\n' ORDER BY product_id,revision_id,reference_id),''),'UTF8')),'hex')
 INTO hashes FROM pg_temp.ps_pdf_stage_reference s;

 IF EXISTS(SELECT FROM pg_temp.ps_pdf_stage_document
 WHERE release_id IS DISTINCT FROM build.release_id
 OR source_digest IS DISTINCT FROM build.source_digest
 OR native_schema_digest IS DISTINCT FROM build.schema_digest) THEN
 RAISE EXCEPTION 'private PDF header binding differs' USING ERRCODE='23514'; END IF;
 digest:=encode(sha256(convert_to(hashes,'UTF8')),'hex');
 SELECT * INTO receipt FROM ops.pdf_stage_receipt WHERE build_id=p_build AND replay_key=p_key;
 IF FOUND THEN
  IF receipt.content_digest IS DISTINCT FROM digest OR receipt.row_count IS DISTINCT FROM total THEN
   RAISE EXCEPTION 'private PDF batch replay differs' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id FROM pg_temp.ps_pdf_stage_document EXCEPT SELECT product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id FROM ops.pdf_stage_document) THEN RAISE EXCEPTION 'private PDF batch replay content differs' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json FROM pg_temp.ps_pdf_stage_native EXCEPT SELECT product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json FROM ops.pdf_stage_native) THEN RAISE EXCEPTION 'private PDF batch replay content differs' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id FROM pg_temp.ps_pdf_stage_membership EXCEPT SELECT product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id FROM ops.pdf_stage_membership) THEN RAISE EXCEPTION 'private PDF batch replay content differs' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id FROM pg_temp.ps_pdf_stage_reference EXCEPT SELECT product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id FROM ops.pdf_stage_reference) THEN RAISE EXCEPTION 'private PDF batch replay content differs' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile FROM pg_temp.ps_pdf_stage_artifact_stream EXCEPT SELECT product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile FROM ops.pdf_stage_artifact_stream) THEN RAISE EXCEPTION 'private PDF batch replay content differs' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest FROM pg_temp.ps_pdf_stage_artifact_part EXCEPT SELECT product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest FROM ops.pdf_stage_artifact_part) THEN RAISE EXCEPTION 'private PDF batch replay content differs' USING ERRCODE='23514'; END IF;
  RETURN NEXT receipt; RETURN;
 END IF;
INSERT INTO ops.pdf_stage_document(product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id) SELECT product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id FROM pg_temp.ps_pdf_stage_document ON CONFLICT DO NOTHING;
IF EXISTS(SELECT product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id FROM pg_temp.ps_pdf_stage_document EXCEPT SELECT product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id FROM ops.pdf_stage_document) THEN RAISE EXCEPTION 'changed private record duplicate' USING ERRCODE='23514'; END IF;
INSERT INTO ops.pdf_stage_native(product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json) SELECT product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json FROM pg_temp.ps_pdf_stage_native ON CONFLICT DO NOTHING;
IF EXISTS(SELECT product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json FROM pg_temp.ps_pdf_stage_native EXCEPT SELECT product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json FROM ops.pdf_stage_native) THEN RAISE EXCEPTION 'changed private record duplicate' USING ERRCODE='23514'; END IF;
INSERT INTO ops.pdf_stage_membership(product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id) SELECT product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id FROM pg_temp.ps_pdf_stage_membership ON CONFLICT DO NOTHING;
IF EXISTS(SELECT product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id FROM pg_temp.ps_pdf_stage_membership EXCEPT SELECT product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id FROM ops.pdf_stage_membership) THEN RAISE EXCEPTION 'changed private record duplicate' USING ERRCODE='23514'; END IF;
INSERT INTO ops.pdf_stage_reference(product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id) SELECT product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id FROM pg_temp.ps_pdf_stage_reference ON CONFLICT DO NOTHING;
IF EXISTS(SELECT product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id FROM pg_temp.ps_pdf_stage_reference EXCEPT SELECT product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id FROM ops.pdf_stage_reference) THEN RAISE EXCEPTION 'changed private record duplicate' USING ERRCODE='23514'; END IF;
INSERT INTO ops.pdf_stage_artifact_stream(product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile) SELECT product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile FROM pg_temp.ps_pdf_stage_artifact_stream ON CONFLICT DO NOTHING;
IF EXISTS(SELECT product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile FROM pg_temp.ps_pdf_stage_artifact_stream EXCEPT SELECT product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile FROM ops.pdf_stage_artifact_stream) THEN RAISE EXCEPTION 'changed private record duplicate' USING ERRCODE='23514'; END IF;
INSERT INTO ops.pdf_stage_artifact_part(product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest) SELECT product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest FROM pg_temp.ps_pdf_stage_artifact_part ON CONFLICT DO NOTHING;
IF EXISTS(SELECT product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest FROM pg_temp.ps_pdf_stage_artifact_part EXCEPT SELECT product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest FROM ops.pdf_stage_artifact_part) THEN RAISE EXCEPTION 'changed private record duplicate' USING ERRCODE='23514'; END IF;

 INSERT INTO ops.pdf_stage_receipt VALUES(p_build,p_key,digest,total) RETURNING * INTO receipt;
 RETURN NEXT receipt;
END $stage$;
CREATE OR REPLACE FUNCTION ops.inspect_pdf_progress(p_build text,p_task bigint,p_attempt bigint,
 p_holder text)
RETURNS SETOF ops.pdf_stage_receipt LANGUAGE plpgsql SECURITY DEFINER SET
 search_path=pg_catalog,pg_temp AS $stage$
DECLARE build ops.pdf_stage_build;
BEGIN
 build:=ops.require_pdf_build(p_build,p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(build.release_id,'inspect_pdf_progress');
 RETURN QUERY SELECT * FROM ops.pdf_stage_receipt WHERE build_id=p_build ORDER BY replay_key;
END $stage$;
CREATE OR REPLACE FUNCTION ops.resume_pdf_build(p_build text,p_task bigint,p_attempt bigint,
 p_holder text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $stage$
DECLARE run ops.run; build ops.pdf_stage_build;
BEGIN
 run:=ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(run.release_id,'resume_pdf_build');
 IF p_build IS NULL THEN RAISE EXCEPTION 'private PDF resume binding differs'
 USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT build FROM ops.pdf_stage_build WHERE build_id=p_build AND task_id=p_task
 FOR UPDATE;
 IF build.release_id IS DISTINCT FROM run.release_id OR build.state NOT IN ('open','frozen')
 OR build.attempt>p_attempt THEN
 RAISE EXCEPTION 'private PDF resume binding differs' USING ERRCODE='23514'; END IF;
 UPDATE ops.pdf_stage_build SET attempt=p_attempt,holder=p_holder WHERE build_id=p_build;
END $stage$;
CREATE OR REPLACE FUNCTION ops.abandon_pdf_build(p_build text,p_task bigint,p_attempt bigint,
 p_holder text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $stage$
DECLARE build ops.pdf_stage_build;
BEGIN
 build:=ops.require_pdf_build(p_build,p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(build.release_id,'abandon_pdf_build');
 IF NOT ops.execution_edge(build.release_id,'pdf_private_build','open','abandoned') THEN
 RAISE EXCEPTION 'private PDF abandonment transition unavailable' USING ERRCODE='23514'; END IF;
 UPDATE ops.pdf_stage_build SET state='abandoned' WHERE build_id=p_build;
END $stage$;
REVOKE ALL ON FUNCTION ops.begin_pdf_build(bigint,bigint,text,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION ops.begin_pdf_build(bigint,bigint,text,text,text,text,text) TO corpus_sem_writer;
REVOKE ALL ON FUNCTION ops.prepare_pdf_stage(text,bigint,bigint,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION ops.prepare_pdf_stage(text,bigint,bigint,text) TO corpus_sem_writer;
REVOKE ALL ON FUNCTION ops.adopt_pdf_batch(text,bigint,bigint,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION ops.adopt_pdf_batch(text,bigint,bigint,text,text) TO corpus_sem_writer;
REVOKE ALL ON FUNCTION ops.inspect_pdf_progress(text,bigint,bigint,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION ops.inspect_pdf_progress(text,bigint,bigint,text) TO corpus_sem_writer;
REVOKE ALL ON FUNCTION ops.resume_pdf_build(text,bigint,bigint,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION ops.resume_pdf_build(text,bigint,bigint,text) TO corpus_sem_writer;
REVOKE ALL ON FUNCTION ops.abandon_pdf_build(text,bigint,bigint,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION ops.abandon_pdf_build(text,bigint,bigint,text) TO corpus_sem_writer;
-- pdf-publication-records-v1 over the pdf-record-sha256-fold-v1 algorithm.
-- Only bounded per-record arrays are constructed; the ordered relation cursor spills normally.
CREATE OR REPLACE FUNCTION ops.pdf_identity_inline(p_value jsonb)
RETURNS bytea LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
DECLARE kind_ text:=jsonb_typeof(p_value); payload_ bytea;
BEGIN
 CASE kind_
 WHEN 'null' THEN RETURN ops.pdf_identity_scalar('n',''::bytea);
 WHEN 'boolean' THEN RETURN ops.pdf_identity_scalar('b',CASE WHEN p_value='true'::jsonb THEN decode('01','hex') ELSE decode('00','hex') END);
 WHEN 'string' THEN RETURN ops.pdf_identity_scalar('s',convert_to(p_value#>>'{}','UTF8'));
 WHEN 'number' THEN RETURN ops.pdf_identity_scalar('i',convert_to(p_value::text,'UTF8'));
 WHEN 'object' THEN
  IF (SELECT count(*) FROM jsonb_object_keys(p_value))<>1 OR
     NOT p_value ? 'native_float64' OR (p_value->>'native_float64') !~ '^[0-9a-f]{16}$' THEN
   RAISE EXCEPTION 'invalid native binary64 inline representation' USING ERRCODE='23514';
  END IF;
  RETURN ops.pdf_identity_scalar('f',decode(p_value->>'native_float64','hex'));
 ELSE RAISE EXCEPTION 'unsupported inline scalar kind %',kind_ USING ERRCODE='23514';
 END CASE;
END $$;

-- Match Python ensure_ascii=True string spelling used by native membership keys.
CREATE OR REPLACE FUNCTION ops.pdf_identity_ascii_string(p_text text)
RETURNS text LANGUAGE plpgsql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
DECLARE out_ text:='"'; c_ text; n_ integer; i_ integer;
BEGIN
 FOR i_ IN 1..char_length(p_text) LOOP
  c_:=substr(p_text,i_,1); n_:=ascii(c_);
  IF n_=34 THEN out_:=out_||chr(92)||'"';
  ELSIF n_=92 THEN out_:=out_||chr(92)||chr(92);
  ELSIF n_=8 THEN out_:=out_||chr(92)||'b';
  ELSIF n_=9 THEN out_:=out_||chr(92)||'t';
  ELSIF n_=10 THEN out_:=out_||chr(92)||'n';
  ELSIF n_=12 THEN out_:=out_||chr(92)||'f';
  ELSIF n_=13 THEN out_:=out_||chr(92)||'r';
  ELSIF n_<32 OR n_>126 THEN
   IF n_<=65535 THEN out_:=out_||chr(92)||'u'||lpad(to_hex(n_),4,'0');
   ELSE
    n_:=n_-65536;
    out_:=out_||chr(92)||'u'||to_hex(55296+n_/1024)||chr(92)||'u'||to_hex(56320+n_%1024);
   END IF;
  ELSE out_:=out_||c_;
  END IF;
 END LOOP;
 RETURN out_||'"';
END $$;

CREATE OR REPLACE FUNCTION ops.pdf_identity_stream_scalar(p_product text,p_revision text,p_stream text)
RETURNS bytea LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
DECLARE stream_ ops.pdf_artifact_stream; kind_ text;
BEGIN
 SELECT * INTO STRICT stream_ FROM ops.pdf_artifact_stream
 WHERE product_id=p_product AND revision_id=p_revision AND stream_id=p_stream;
 PERFORM ops.pdf_identity_verify_artifact(p_product,p_revision,p_stream);
 IF stream_.encoding_profile IN ('pdf-record-native-json-v1','pdf-companion-json-field-v1') THEN kind_:='y';
 ELSIF stream_.encoding_profile ~ '^pdf-record-scalar-v1:[anbifsyd]$' THEN
  kind_:=right(stream_.encoding_profile,1);
 ELSE RAISE EXCEPTION 'stream is not a native scalar profile' USING ERRCODE='23514'; END IF;
 RETURN convert_to(kind_,'UTF8')||int8send(stream_.byte_length)||decode(stream_.byte_root,'hex');
END $$;

CREATE OR REPLACE FUNCTION ops.pdf_identity_companion_scalar(
 p_product text,p_revision text,p_family text,p_local text,p_field text,p_body jsonb)
RETURNS bytea LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
DECLARE field_ kb.pdf_record_companion_field; stream_ ops.pdf_artifact_stream;
BEGIN
 SELECT * INTO field_ FROM kb.pdf_record_companion_field WHERE product_id=p_product
 AND revision_id=p_revision AND family=p_family AND local_id=p_local AND field_name=p_field;
 IF FOUND THEN
  IF p_body ? p_field THEN RAISE EXCEPTION 'companion field has competing inline and external values' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT stream_ FROM ops.pdf_artifact_stream WHERE product_id=p_product
   AND revision_id=p_revision AND stream_id=field_.stream_id;
  IF (p_field='value' AND (p_family<>'native_metadata' OR field_.scalar_kind<>'y'
    OR stream_.encoding_profile<>'pdf-companion-json-field-v1'))
   OR (p_field='text' AND (p_family<>'occurrence' OR field_.scalar_kind<>'s'
    OR stream_.encoding_profile<>'pdf-record-scalar-v1:s')) THEN
   RAISE EXCEPTION 'companion field profile differs' USING ERRCODE='23514';
  END IF;
  RETURN ops.pdf_identity_stream_scalar(p_product,p_revision,field_.stream_id);
 END IF;
 IF p_family='native_metadata' THEN
  RAISE EXCEPTION 'metadata value requires its declared JSON byte stream' USING ERRCODE='23514';
 END IF;
 IF NOT p_body ? p_field THEN RETURN ops.pdf_identity_scalar('a',''::bytea); END IF;
 IF jsonb_typeof(p_body->p_field) NOT IN ('null','string') THEN
  RAISE EXCEPTION 'occurrence text must be string or null' USING ERRCODE='23514'; END IF;
 RETURN ops.pdf_identity_inline(p_body->p_field);
END $$;

CREATE OR REPLACE FUNCTION ops.pdf_record_logical_identity(p_product text,p_revision text)
RETURNS text LANGUAGE plpgsql STABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
DECLARE header_ ops.pdf_record_document; row_ record; node_ kb.pdf_record_native;
 member_ kb.pdf_record_membership; field_ text; descriptor_ jsonb;
 names_ text[]; values_ bytea[]; frame_ bytea; key_ text; key_scalar_ bytea;
 state_ bytea:=ops.pdf_identity_fold_start('records'); count_ bigint:=0; length_ bigint:=0;
BEGIN
 SELECT * INTO STRICT header_ FROM ops.pdf_record_document WHERE product_id=p_product AND revision_id=p_revision;
 frame_:=ops.pdf_identity_record_frame(header_.native_schema_digest,'@context','@context',
 ARRAY['protocol','release','source'],ARRAY[
 ops.pdf_identity_scalar('s',convert_to('pdf-record-sha256-fold-v1','UTF8')),
 ops.pdf_identity_scalar('s',convert_to(header_.release_id,'UTF8')),
 ops.pdf_identity_scalar('s',convert_to(header_.source_digest,'UTF8'))]);
 state_:=ops.pdf_identity_fold_step(state_,count_,frame_); count_:=count_+1; length_:=length_+octet_length(frame_);
 FOR row_ IN
  SELECT * FROM (SELECT 'companion/'||c.family AS family,c.local_id AS key, NULL::text AS parent_key,NULL::text AS field_key,NULL::bigint AS ordinal_key FROM kb.pdf_record_companion c
   WHERE c.product_id=p_product AND c.revision_id=p_revision
  UNION ALL SELECT 'document','root',NULL,NULL,NULL
  UNION ALL SELECT 'endpoint','['||ops.pdf_identity_ascii_string(e.relation_id)||','||e.ordinal::text||']',e.relation_id,NULL,e.ordinal
   FROM kb.pdf_record_endpoint e WHERE e.product_id=p_product AND e.revision_id=p_revision
  UNION ALL SELECT 'membership','['||ops.pdf_identity_ascii_string(m.parent_id)||','||
   ops.pdf_identity_ascii_string(m.field_name)||','||CASE
    WHEN m.member_key IS NOT NULL THEN ops.pdf_identity_ascii_string(encode(ops.pdf_identity_scalar('s',convert_to(m.member_key,'UTF8')),'hex'))
    WHEN m.member_key_stream_id IS NOT NULL THEN ops.pdf_identity_ascii_string(encode(ops.pdf_identity_stream_scalar(p_product,p_revision,m.member_key_stream_id),'hex'))
    ELSE m.ordinal::text END||']',m.parent_id,m.field_name,m.ordinal
   FROM kb.pdf_record_membership m WHERE m.product_id=p_product AND m.revision_id=p_revision
  UNION ALL SELECT 'native',n.record_id,NULL,NULL,NULL FROM kb.pdf_record_native n WHERE n.product_id=p_product AND n.revision_id=p_revision
  UNION ALL SELECT 'publication','root',NULL,NULL,NULL
  ) ordered_ ORDER BY family COLLATE "C",key COLLATE "C"
 LOOP
  names_:=ARRAY[]::text[]; values_:=ARRAY[]::bytea[];
  IF row_.family='publication' THEN
   names_:=ARRAY['kind','recipe_digest'];
   SELECT ARRAY[ops.pdf_identity_scalar('s',convert_to(f.kind,'UTF8')),ops.pdf_identity_scalar('s',convert_to(b.recipe_digest,'UTF8'))] INTO STRICT values_
    FROM ops.pdf_frozen_build f JOIN ops.pdf_stage_build b USING(build_id) WHERE f.build_id=p_product;
  ELSIF row_.family='document' THEN
   names_:=ARRAY['mapping_profile','contract_version','native_schema_digest','root_id'];
   values_:=ARRAY[ops.pdf_identity_scalar('s',convert_to(header_.mapping_profile,'UTF8')),
    ops.pdf_identity_scalar('s',convert_to(header_.contract_version,'UTF8')),
    ops.pdf_identity_scalar('s',convert_to(header_.native_schema_digest,'UTF8')),
    ops.pdf_identity_scalar('s',convert_to(header_.root_id,'UTF8'))];
  ELSIF row_.family='native' THEN
   SELECT * INTO STRICT node_ FROM kb.pdf_record_native WHERE product_id=p_product AND revision_id=p_revision AND record_id=row_.key;
   names_:=ARRAY['native_type','family'];
   values_:=ARRAY[ops.pdf_identity_scalar('s',convert_to(node_.native_type,'UTF8')),ops.pdf_identity_scalar('s',convert_to(node_.family,'UTF8'))];
   FOR field_ IN SELECT k FROM (SELECT jsonb_object_keys(node_.scalars_json) k UNION SELECT jsonb_object_keys(node_.structure_json->'fields')) keys_ ORDER BY k COLLATE "C" LOOP
    IF node_.scalars_json ? field_ THEN
     names_:=array_append(names_,field_||'/value'); values_:=array_append(values_,ops.pdf_identity_inline(node_.scalars_json->field_));
    ELSE
     descriptor_:=node_.structure_json->'fields'->field_;
     IF descriptor_->>'kind'='parts' THEN
      names_:=array_append(names_,field_||'/value'); values_:=array_append(values_,ops.pdf_identity_stream_scalar(p_product,p_revision,descriptor_->>'stream_id'));
     ELSE
      names_:=array_append(names_,field_||'/kind'); values_:=array_append(values_,ops.pdf_identity_scalar('s',convert_to(descriptor_->>'kind','UTF8')));
      IF descriptor_->>'kind'='object' THEN
       names_:=array_append(names_,field_||'/target'); values_:=array_append(values_,ops.pdf_identity_scalar('s',convert_to(descriptor_->>'target','UTF8')));
      ELSE
       names_:=array_append(names_,field_||'/length'); values_:=array_append(values_,ops.pdf_identity_scalar('i',convert_to(descriptor_->>'length','UTF8')));
      END IF;
     END IF;
    END IF;
   END LOOP;
   IF node_.structure_json ? 'extensions' THEN
    names_:=array_append(names_,'@extensions'); values_:=array_append(values_,ops.pdf_identity_stream_scalar(p_product,p_revision,node_.structure_json->'extensions'->>'stream_id'));
   END IF;
  ELSIF row_.family='membership' THEN
   -- Key lookup derives from the already ordered cursor and uses the PK, never scans per parent.
   SELECT * INTO STRICT member_ FROM kb.pdf_record_membership m WHERE product_id=p_product AND revision_id=p_revision
    AND m.parent_id=row_.parent_key AND m.field_name=row_.field_key AND m.ordinal=row_.ordinal_key;
   names_:=ARRAY['parent_id','field_name']; values_:=ARRAY[ops.pdf_identity_scalar('s',convert_to(member_.parent_id,'UTF8')),ops.pdf_identity_scalar('s',convert_to(member_.field_name,'UTF8'))];
   IF member_.member_key IS NOT NULL OR member_.member_key_stream_id IS NOT NULL THEN
    names_:=array_append(names_,'member_key');
    key_scalar_:=CASE WHEN member_.member_key IS NOT NULL THEN ops.pdf_identity_scalar('s',convert_to(member_.member_key,'UTF8')) ELSE ops.pdf_identity_stream_scalar(p_product,p_revision,member_.member_key_stream_id) END;
    values_:=array_append(values_,key_scalar_);
   ELSE names_:=array_append(names_,'ordinal'); values_:=array_append(values_,ops.pdf_identity_scalar('i',convert_to(member_.ordinal::text,'UTF8'))); END IF;
   IF member_.value_kind='record' THEN
    names_:=array_append(names_,'target'); values_:=array_append(values_,ops.pdf_identity_scalar('s',convert_to(member_.record_id,'UTF8')));
   ELSE
    names_:=array_append(names_,'value'); values_:=array_append(values_,CASE WHEN member_.value_kind='scalar' THEN ops.pdf_identity_inline(member_.scalar_json) ELSE ops.pdf_identity_stream_scalar(p_product,p_revision,member_.stream_id) END);
   END IF;
  ELSIF left(row_.family,10)='companion/' THEN
   names_:=ARRAY['body','ordinal']; SELECT ARRAY[ops.pdf_identity_scalar('s',convert_to(data.canonical_json(CASE WHEN c.family='native_metadata' THEN c.body-'value' WHEN c.family='occurrence' THEN c.body-'text' ELSE c.body END),'UTF8')),ops.pdf_identity_scalar('i',convert_to(c.ordinal::text,'UTF8'))] INTO values_ FROM kb.pdf_record_companion c
    WHERE c.product_id=p_product AND c.revision_id=p_revision AND c.family=substr(row_.family,11) AND c.local_id=row_.key;
   IF row_.family IN ('companion/native_metadata','companion/occurrence') THEN
    field_:=CASE WHEN row_.family='companion/native_metadata' THEN 'value' ELSE 'text' END;
    names_:=array_append(names_,field_);
    SELECT array_append(values_,ops.pdf_identity_companion_scalar(p_product,p_revision,c.family,c.local_id,field_,c.body))
     INTO values_ FROM kb.pdf_record_companion c WHERE c.product_id=p_product AND c.revision_id=p_revision
     AND c.family=substr(row_.family,11) AND c.local_id=row_.key;
   END IF;

  ELSIF row_.family='endpoint' THEN
   names_:=ARRAY['relation_id','ordinal','target_task_id','target_product_key','target_content_digest','occurrence_id','role'];
   SELECT ARRAY[ops.pdf_identity_scalar('s',convert_to(e.relation_id,'UTF8')),ops.pdf_identity_scalar('i',convert_to(e.ordinal::text,'UTF8')),
    ops.pdf_identity_scalar('i',convert_to(e.target_task_id::text,'UTF8')),ops.pdf_identity_scalar('s',convert_to(e.target_product_key,'UTF8')),
    ops.pdf_identity_scalar('s',convert_to(e.target_content_digest,'UTF8')),ops.pdf_identity_scalar('s',convert_to(e.occurrence_id,'UTF8')),ops.pdf_identity_scalar('s',convert_to(e.role,'UTF8'))] INTO values_
    FROM kb.pdf_record_endpoint e WHERE e.product_id=p_product AND e.revision_id=p_revision AND e.relation_id=row_.parent_key AND e.ordinal=row_.ordinal_key;
  END IF;
  frame_:=ops.pdf_identity_record_frame(header_.native_schema_digest,row_.family,row_.key,names_,values_);
  state_:=ops.pdf_identity_fold_step(state_,count_,frame_); count_:=count_+1; length_:=length_+octet_length(frame_);
 END LOOP;
 RETURN encode(ops.pdf_identity_fold_finish(state_,count_,length_),'hex');
END $$;
REVOKE ALL ON FUNCTION ops.pdf_identity_inline(jsonb),ops.pdf_identity_ascii_string(text),
 ops.pdf_identity_stream_scalar(text,text,text),
 ops.pdf_identity_companion_scalar(text,text,text,text,text,jsonb),ops.pdf_record_logical_identity(text,text) FROM PUBLIC;

-- Private access projections are derived from the same frozen native records.
-- JSONB projection equality intentionally permits numeric lexical normalization and
-- signed-zero loss; the separately checked native record/byte identity retains both.
CREATE OR REPLACE FUNCTION ops.pdf_projection_scalar_matches(p_value jsonb,p_expected jsonb)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE actual_ bytea; expected_ bytea;
BEGIN
 IF p_value IS NULL OR p_expected IS NULL THEN RETURN false; END IF;
 IF jsonb_typeof(p_expected)='object' AND p_expected ? 'native_float64' THEN
  IF jsonb_typeof(p_value)<>'number' THEN RETURN false; END IF;
  actual_:=float8send((p_value#>>'{}')::double precision);
  expected_:=decode(p_expected->>'native_float64','hex');
  RETURN actual_=expected_ OR (expected_ IN (decode('0000000000000000','hex'),decode('8000000000000000','hex')) AND (p_value#>>'{}')::numeric=0);
 END IF;
 RETURN jsonb_typeof(p_value)=jsonb_typeof(p_expected) AND p_value=p_expected;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION ops.pdf_projection_stream_value(p_build text,p_stream text)
RETURNS jsonb LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE stream_ ops.pdf_artifact_stream; actual_length_ bigint; payload_ bytea;
BEGIN
 SELECT * INTO STRICT stream_ FROM ops.pdf_artifact_stream WHERE product_id=p_build AND revision_id=p_build AND stream_id=p_stream;
 -- A per-item projection is admitted through the existing 8MiB access-upload
 -- profile. Only its own opaque/key value is decoded here, never a book envelope.
 SELECT COALESCE(sum(octet_length(body)),0) INTO actual_length_ FROM ops.pdf_artifact_part
 WHERE product_id=p_build AND revision_id=p_build AND stream_id=p_stream;
 IF actual_length_>8388608 OR actual_length_<>stream_.byte_length THEN
  RAISE EXCEPTION 'native access scalar exceeds bounded projection or stream length' USING ERRCODE='23514'; END IF;
 SELECT COALESCE(string_agg(body,''::bytea ORDER BY ordinal),''::bytea) INTO payload_ FROM ops.pdf_artifact_part
 WHERE product_id=p_build AND revision_id=p_build AND stream_id=p_stream;
 IF stream_.encoding_profile='pdf-record-native-json-v1' THEN RETURN convert_from(payload_,'UTF8')::jsonb;
 ELSIF stream_.encoding_profile='pdf-record-scalar-v1:s' THEN RETURN to_jsonb(convert_from(payload_,'UTF8'));
 ELSE RAISE EXCEPTION 'native access requires a JSON/string stream profile' USING ERRCODE='23514'; END IF;
END $$;

CREATE OR REPLACE FUNCTION ops.pdf_projection_stream_matches(p_build text,p_stream text,p_value jsonb)
RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE stream_ ops.pdf_artifact_stream; payload_ bytea;
BEGIN
 IF p_value IS NULL THEN RETURN false; END IF;
 SELECT * INTO STRICT stream_ FROM ops.pdf_artifact_stream WHERE product_id=p_build AND revision_id=p_build AND stream_id=p_stream;
 IF stream_.encoding_profile='pdf-record-native-json-v1' THEN
  RETURN ops.pdf_projection_stream_value(p_build,p_stream)=p_value;
 ELSIF stream_.encoding_profile='pdf-record-scalar-v1:s' AND jsonb_typeof(p_value)='string' THEN
  payload_:=convert_to(p_value#>>'{}','UTF8');
 ELSIF stream_.encoding_profile='pdf-record-scalar-v1:i' AND jsonb_typeof(p_value)='number' THEN
  IF (p_value#>>'{}') !~ '^(0|-?[1-9][0-9]*)$' THEN RETURN false; END IF;
  payload_:=convert_to(p_value#>>'{}','UTF8');
 ELSIF stream_.encoding_profile='pdf-record-scalar-v1:f' AND jsonb_typeof(p_value)='number' THEN
  payload_:=float8send((p_value#>>'{}')::double precision);
  IF (p_value#>>'{}')::numeric=0 AND stream_.byte_length=8 AND stream_.byte_root IN
   (encode(ops.pdf_identity_byte_root(decode('0000000000000000','hex')),'hex'),encode(ops.pdf_identity_byte_root(decode('8000000000000000','hex')),'hex')) THEN RETURN true; END IF;
 ELSIF stream_.encoding_profile='pdf-record-scalar-v1:n' AND p_value='null'::jsonb THEN payload_:=''::bytea;
 ELSIF stream_.encoding_profile='pdf-record-scalar-v1:b' AND jsonb_typeof(p_value)='boolean' THEN
  payload_:=CASE WHEN p_value='true'::jsonb THEN decode('01','hex') ELSE decode('00','hex') END;
 ELSE RETURN false;
 END IF;
 RETURN octet_length(payload_)=stream_.byte_length AND encode(ops.pdf_identity_byte_root(payload_),'hex')=stream_.byte_root;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END $$;

CREATE OR REPLACE FUNCTION ops.pdf_check_access_correspondence(p_build text)
RETURNS void LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF EXISTS(SELECT FROM kb.pdf_record_access a LEFT JOIN kb.pdf_record_native n
 ON n.product_id=p_build AND n.revision_id=p_build AND n.native_address=a.pointer
 WHERE a.product_id=p_build AND (a.revision_id<>p_build OR n.record_id IS NULL OR
 a.native_json->>'self_ref' IS DISTINCT FROM a.pointer OR
 a.label IS DISTINCT FROM COALESCE(a.native_json->>'label','unspecified') OR
 a.content_layer IS DISTINCT FROM COALESCE(a.native_json->>'content_layer','body') OR
 a.text IS DISTINCT FROM a.native_json->>'text' OR
 a.parent_pointer IS DISTINCT FROM a.native_json#>>'{parent,$ref}')) THEN
 RAISE EXCEPTION 'native access fields do not correspond to frozen native item' USING ERRCODE='23514'; END IF;

 IF EXISTS(WITH RECURSIVE projected(record_id,value) AS (
  SELECT n.record_id,a.native_json FROM kb.pdf_record_access a JOIN kb.pdf_record_native n
  ON n.product_id=p_build AND n.revision_id=p_build AND n.native_address=a.pointer WHERE a.product_id=p_build
  UNION ALL
  SELECT child.record_id,child.value FROM projected w JOIN kb.pdf_record_native n
  ON n.product_id=p_build AND n.revision_id=p_build AND n.record_id=w.record_id
  CROSS JOIN LATERAL (
   SELECT f.value->>'target' AS record_id,w.value->f.key AS value
   FROM jsonb_each(n.structure_json->'fields') f WHERE f.value->>'kind'='object'
   UNION ALL
   SELECT m.record_id,CASE WHEN f.value->>'kind'='map' THEN container.value->COALESCE(m.member_key,ops.pdf_projection_stream_value(p_build,m.member_key_stream_id)#>>'{}') ELSE container.value->m.ordinal::integer END
   FROM jsonb_each(n.structure_json->'fields') f JOIN kb.pdf_record_membership m
   ON m.product_id=p_build AND m.revision_id=p_build AND m.parent_id=w.record_id AND m.field_name=f.key
   CROSS JOIN LATERAL (SELECT CASE WHEN n.native_type='NativeArray' AND f.key='items' THEN w.value ELSE w.value->f.key END value) container
   WHERE f.value->>'kind' IN ('array','map') AND m.value_kind='record'
  ) child
 ) CYCLE record_id SET cycle_ USING path_
 SELECT FROM projected w LEFT JOIN kb.pdf_record_native n
 ON n.product_id=p_build AND n.revision_id=p_build AND n.record_id=w.record_id
 WHERE w.cycle_ OR n.record_id IS NULL OR w.value IS NULL OR
 (n.native_type='NativeArray' AND jsonb_typeof(w.value)<>'array') OR
 (n.native_type<>'NativeArray' AND (jsonb_typeof(w.value)<>'object' OR
  CASE WHEN n.structure_json ? 'extensions' THEN
    ops.pdf_projection_stream_matches(p_build,n.structure_json->'extensions'->>'stream_id',
     w.value-ARRAY(SELECT jsonb_object_keys(n.scalars_json) UNION SELECT jsonb_object_keys(n.structure_json->'fields'))) IS NOT TRUE
  ELSE w.value-ARRAY(SELECT jsonb_object_keys(n.scalars_json) UNION SELECT jsonb_object_keys(n.structure_json->'fields'))<>'{}'::jsonb END)) OR
 EXISTS(SELECT FROM jsonb_each(n.scalars_json) s WHERE ops.pdf_projection_scalar_matches(w.value->s.key,s.value) IS NOT TRUE) OR
 EXISTS(SELECT FROM jsonb_each(n.structure_json->'fields') f
 CROSS JOIN LATERAL (SELECT CASE WHEN n.native_type='NativeArray' AND f.key='items' THEN w.value ELSE w.value->f.key END value) container
 WHERE container.value IS NULL OR
 (f.value->>'kind'='object' AND jsonb_typeof(container.value)<>'object') OR
 (f.value->>'kind'='parts' AND ops.pdf_projection_stream_matches(p_build,f.value->>'stream_id',container.value) IS NOT TRUE) OR
 (f.value->>'kind'='array' AND (jsonb_typeof(container.value)<>'array' OR jsonb_array_length(container.value)<>(f.value->>'length')::bigint)) OR
 (f.value->>'kind'='map' AND (jsonb_typeof(container.value)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(container.value))<>(f.value->>'length')::bigint)) OR
 EXISTS(SELECT FROM kb.pdf_record_membership m
 CROSS JOIN LATERAL (SELECT CASE WHEN f.value->>'kind'='map' THEN container.value->COALESCE(m.member_key,ops.pdf_projection_stream_value(p_build,m.member_key_stream_id)#>>'{}') ELSE container.value->m.ordinal::integer END value) actual
 WHERE m.product_id=p_build AND m.revision_id=p_build AND m.parent_id=w.record_id AND m.field_name=f.key AND
 (actual.value IS NULL OR (m.value_kind='scalar' AND ops.pdf_projection_scalar_matches(actual.value,m.scalar_json) IS NOT TRUE) OR
 (m.value_kind='parts' AND ops.pdf_projection_stream_matches(p_build,m.stream_id,actual.value) IS NOT TRUE))))) THEN
 RAISE EXCEPTION 'native access JSON differs from frozen record fields/members/scalars' USING ERRCODE='23514'; END IF;

 IF EXISTS(WITH RECURSIVE ancestry(pointer,owner,depth) AS (
  SELECT pointer,pointer,0 FROM kb.pdf_record_access WHERE product_id=p_build
  UNION ALL SELECT a.pointer,parent.pointer,a.depth+1 FROM ancestry a JOIN kb.pdf_record_access child
  ON child.product_id=p_build AND child.pointer=a.owner JOIN kb.pdf_record_access parent
  ON parent.product_id=p_build AND parent.pointer=child.parent_pointer
 ) CYCLE owner SET cycle_ USING path_, nearest AS (
 SELECT DISTINCT ON (n.pointer) n.pointer,n.owner FROM ancestry n JOIN kb.pdf_record_access section
 ON section.product_id=p_build AND section.revision_id=p_build AND section.pointer=n.owner
 WHERE section.label IN ('section','chapter') ORDER BY n.pointer,n.depth
 ), cycles AS (SELECT DISTINCT pointer FROM ancestry WHERE cycle_)
 SELECT FROM kb.pdf_record_access a LEFT JOIN nearest n ON n.pointer=a.pointer
 LEFT JOIN cycles c ON c.pointer=a.pointer WHERE a.product_id=p_build AND
 (c.pointer IS NOT NULL OR a.section_pointer IS DISTINCT FROM n.owner)) THEN
 RAISE EXCEPTION 'native access section owner differs from native ancestry' USING ERRCODE='23514'; END IF;

 IF EXISTS(WITH RECURSIVE roots(pointer,path) AS (
  SELECT target.scalars_json->>'self_ref',ARRAY[CASE f.key WHEN 'body' THEN 0 ELSE 1 END]::bigint[]
  FROM ops.pdf_record_document h JOIN kb.pdf_record_native root ON root.product_id=p_build AND root.record_id=h.root_id
  CROSS JOIN LATERAL jsonb_each(root.structure_json->'fields') f JOIN kb.pdf_record_native target
  ON target.product_id=p_build AND target.record_id=f.value->>'target' WHERE h.product_id=p_build AND f.key IN ('body','furniture')
 ), traversal(pointer,path) AS (
 SELECT pointer,path FROM roots UNION ALL
 SELECT c.value->>'$ref',t.path||(c.ordinality-1) FROM traversal t JOIN kb.pdf_record_access a
 ON a.product_id=p_build AND a.pointer=t.pointer CROSS JOIN LATERAL jsonb_array_elements(COALESCE(a.native_json->'children','[]')) WITH ORDINALITY c
 ) CYCLE pointer SET cycle_ USING cycle_path_
 SELECT FROM (SELECT a.pointer,a.ordinal,row_number() OVER(ORDER BY CASE WHEN t.pointer IS NULL THEN 1 ELSE 0 END,t.path,a.pointer COLLATE "C")-1 expected,t.cycle_
 FROM kb.pdf_record_access a LEFT JOIN traversal t ON t.pointer=a.pointer WHERE a.product_id=p_build) ordered
 WHERE ordinal<>expected OR cycle_) THEN
 RAISE EXCEPTION 'native access order differs from native containment traversal' USING ERRCODE='23514'; END IF;

 IF EXISTS(SELECT FROM kb.pdf_record_access a WHERE a.product_id=p_build AND
 (SELECT count(*) FROM kb.pdf_record_region r WHERE r.product_id=p_build AND r.revision_id=p_build AND r.pointer=a.pointer)<>jsonb_array_length(COALESCE(a.native_json->'prov','[]'))) OR
 EXISTS(SELECT FROM kb.pdf_record_region r LEFT JOIN kb.pdf_record_access a ON a.product_id=p_build AND a.pointer=r.pointer
 LEFT JOIN LATERAL (SELECT a.native_json->'prov'->r.region_index::integer value) prov ON true
 LEFT JOIN ops.pdf_record_document h ON h.product_id=p_build AND h.revision_id=p_build
 LEFT JOIN kb.pdf_record_membership pages ON pages.product_id=p_build AND pages.revision_id=p_build AND pages.parent_id=h.root_id AND pages.field_name='pages' AND pages.member_key=r.page_no::text
 LEFT JOIN kb.pdf_record_native page ON page.product_id=p_build AND page.record_id=pages.record_id
 LEFT JOIN kb.pdf_record_native size ON size.product_id=p_build AND size.record_id=page.structure_json->'fields'->'size'->>'target'
 WHERE r.product_id=p_build AND (r.revision_id<>p_build OR a.pointer IS NULL OR prov.value IS NULL OR
 (prov.value->>'page_no')::bigint IS DISTINCT FROM r.page_no OR
 ops.pdf_projection_scalar_matches(to_jsonb(r.page_width),size.scalars_json->'width') IS NOT TRUE OR
 ops.pdf_projection_scalar_matches(to_jsonb(r.page_height),size.scalars_json->'height') IS NOT TRUE OR
 to_jsonb(r.left) IS DISTINCT FROM prov.value->'bbox'->'l' OR to_jsonb(r.top) IS DISTINCT FROM prov.value->'bbox'->'t' OR
 to_jsonb(r.right) IS DISTINCT FROM prov.value->'bbox'->'r' OR to_jsonb(r.bottom) IS DISTINCT FROM prov.value->'bbox'->'b' OR
 r.origin IS DISTINCT FROM CASE prov.value->'bbox'->>'coord_origin' WHEN 'TOPLEFT' THEN 'top_left' WHEN 'BOTTOMLEFT' THEN 'bottom_left' END)) THEN
 RAISE EXCEPTION 'native access regions differ from native provenance/pages' USING ERRCODE='23514'; END IF;
END $$;

REVOKE ALL ON FUNCTION ops.pdf_projection_scalar_matches(jsonb,jsonb),ops.pdf_projection_stream_value(text,text),
 ops.pdf_projection_stream_matches(text,text,jsonb),ops.pdf_check_access_correspondence(text) FROM PUBLIC;


