WHEN 'FieldHeadingItem' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['self_ref','parent','children','content_layer','meta','label','prov','source','comments','orig','text','formatting','hyperlink','level']::text[])) AND (p_scalars ? 'self_ref' OR p_fields ? 'self_ref') AND (p_scalars ? 'orig' OR p_fields ? 'orig') AND (p_scalars ? 'text' OR p_fields ? 'text') AND (NOT p_scalars ? 'self_ref' OR ((jsonb_typeof(p_scalars->'self_ref')='string'))) AND (NOT p_scalars ? 'parent' OR ((jsonb_typeof(p_scalars->'parent')='null'))) AND (NOT p_scalars ? 'children' OR (false)) AND (NOT p_scalars ? 'content_layer' OR ((jsonb_typeof(p_scalars->'content_layer')='string' AND p_scalars->'content_layer' IN ('"body"'::jsonb,'"furniture"'::jsonb,'"background"'::jsonb,'"invisible"'::jsonb,'"notes"'::jsonb)))) AND (NOT p_scalars ? 'meta' OR ((jsonb_typeof(p_scalars->'meta')='null'))) AND (NOT p_scalars ? 'label' OR ((jsonb_typeof(p_scalars->'label')='string' AND p_scalars->'label'='"field_heading"'::jsonb))) AND (NOT p_scalars ? 'prov' OR (false)) AND (NOT p_scalars ? 'source' OR (false)) AND (NOT p_scalars ? 'comments' OR (false)) AND (NOT p_scalars ? 'orig' OR ((jsonb_typeof(p_scalars->'orig')='string'))) AND (NOT p_scalars ? 'text' OR ((jsonb_typeof(p_scalars->'text')='string'))) AND (NOT p_scalars ? 'formatting' OR ((jsonb_typeof(p_scalars->'formatting')='null'))) AND (NOT p_scalars ? 'hyperlink' OR ((jsonb_typeof(p_scalars->'hyperlink')='string') OR (jsonb_typeof(p_scalars->'hyperlink')='string') OR (jsonb_typeof(p_scalars->'hyperlink')='null'))) AND (NOT p_scalars ? 'level' OR (((jsonb_typeof(p_scalars->'level')='number' AND (p_scalars->'level'::text) ~ '^-?[0-9]+$'))));
