WHEN 'TextItem' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['self_ref','parent','children','content_layer','meta','label','prov','source','comments','orig','text','formatting','hyperlink']::text[])) AND (p_scalars ? 'self_ref' OR p_fields ? 'self_ref') AND (p_scalars ? 'label' OR p_fields ? 'label') AND (p_scalars ? 'orig' OR p_fields ? 'orig') AND (p_scalars ? 'text' OR p_fields ? 'text') AND (NOT p_scalars ? 'self_ref' OR ((jsonb_typeof(p_scalars->'self_ref')='string'))) AND (NOT p_scalars ? 'parent' OR ((jsonb_typeof(p_scalars->'parent')='null'))) AND (NOT p_scalars ? 'children' OR (false)) AND (NOT p_scalars ? 'content_layer' OR ((jsonb_typeof(p_scalars->'content_layer')='string' AND p_scalars->'content_layer' IN ('"body"'::jsonb,'"furniture"'::jsonb,'"background"'::jsonb,'"invisible"'::jsonb,'"notes"'::jsonb)))) AND (NOT p_scalars ? 'meta' OR ((jsonb_typeof(p_scalars->'meta')='null'))) AND (NOT p_scalars ? 'label' OR ((jsonb_typeof(p_scalars->'label')='string' AND p_scalars->'label' IN ('"caption"'::jsonb,'"checkbox_selected"'::jsonb,'"checkbox_unselected"'::jsonb,'"footnote"'::jsonb,'"page_footer"'::jsonb,'"page_header"'::jsonb,'"paragraph"'::jsonb,'"reference"'::jsonb,'"text"'::jsonb,'"empty_value"'::jsonb,'"field_key"'::jsonb,'"field_hint"'::jsonb,'"marker"'::jsonb,'"handwritten_text"'::jsonb)))) AND (NOT p_scalars ? 'prov' OR (false)) AND (NOT p_scalars ? 'source' OR (false)) AND (NOT p_scalars ? 'comments' OR (false)) AND (NOT p_scalars ? 'orig' OR ((jsonb_typeof(p_scalars->'orig')='string'))) AND (NOT p_scalars ? 'text' OR ((jsonb_typeof(p_scalars->'text')='string'))) AND (NOT p_scalars ? 'formatting' OR ((jsonb_typeof(p_scalars->'formatting')='null'))) AND (NOT p_scalars ? 'hyperlink' OR ((jsonb_typeof(p_scalars->'hyperlink')='string') OR (jsonb_typeof(p_scalars->'hyperlink')='string') OR (jsonb_typeof(p_scalars->'hyperlink')='null')));
WHEN 'TitleItem' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['self_ref','parent','children','content_layer','meta','label','prov','source','comments','orig','text','formatting','hyperlink']::text[])) AND (p_scalars ? 'self_ref' OR p_fields ? 'self_ref') AND (p_scalars ? 'orig' OR p_fields ? 'orig') AND (p_scalars ? 'text' OR p_fields ? 'text') AND (NOT p_scalars ? 'self_ref' OR ((jsonb_typeof(p_scalars->'self_ref')='string'))) AND (NOT p_scalars ? 'parent' OR ((jsonb_typeof(p_scalars->'parent')='null'))) AND (NOT p_scalars ? 'children' OR (false)) AND (NOT p_scalars ? 'content_layer' OR ((jsonb_typeof(p_scalars->'content_layer')='string' AND p_scalars->'content_layer' IN ('"body"'::jsonb,'"furniture"'::jsonb,'"background"'::jsonb,'"invisible"'::jsonb,'"notes"'::jsonb)))) AND (NOT p_scalars ? 'meta' OR ((jsonb_typeof(p_scalars->'meta')='null'))) AND (NOT p_scalars ? 'label' OR ((jsonb_typeof(p_scalars->'label')='string' AND p_scalars->'label'='"title"'::jsonb))) AND (NOT p_scalars ? 'prov' OR (false)) AND (NOT p_scalars ? 'source' OR (false)) AND (NOT p_scalars ? 'comments' OR (false)) AND (NOT p_scalars ? 'orig' OR ((jsonb_typeof(p_scalars->'orig')='string'))) AND (NOT p_scalars ? 'text' OR ((jsonb_typeof(p_scalars->'text')='string'))) AND (NOT p_scalars ? 'formatting' OR ((jsonb_typeof(p_scalars->'formatting')='null'))) AND (NOT p_scalars ? 'hyperlink' OR ((jsonb_typeof(p_scalars->'hyperlink')='string') OR (jsonb_typeof(p_scalars->'hyperlink')='string') OR (jsonb_typeof(p_scalars->'hyperlink')='null')));
WHEN 'TopicsMetaField' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['values']::text[])) AND (p_scalars ? 'values' OR p_fields ? 'values') AND (NOT p_scalars ? 'values' OR (false));
WHEN 'TrackSource' THEN RETURN NOT EXISTS(SELECT FROM jsonb_object_keys(p_scalars||p_fields) k WHERE NOT k=ANY(ARRAY['kind','start_time','end_time','identifier','voice']::text[])) AND (p_scalars ? 'start_time' OR p_fields ? 'start_time') AND (p_scalars ? 'end_time' OR p_fields ? 'end_time') AND (NOT p_scalars ? 'kind' OR ((jsonb_typeof(p_scalars->'kind')='string' AND p_scalars->'kind'='"track"'::jsonb))) AND (NOT p_scalars ? 'start_time' OR (((jsonb_typeof(p_scalars->'start_time')='number' OR (jsonb_typeof(p_scalars->'start_time')='object' AND p_scalars->'start_time' ? 'native_float64' AND (p_scalars->'start_time'->>'native_float64') ~ '^[0-9a-f]{16}$'))))) AND (NOT p_scalars ? 'end_time' OR (((jsonb_typeof(p_scalars->'end_time')='number' OR (jsonb_typeof(p_scalars->'end_time')='object' AND p_scalars->'end_time' ? 'native_float64' AND (p_scalars->'end_time'->>'native_float64') ~ '^[0-9a-f]{16}$'))))) AND (NOT p_scalars ? 'identifier' OR ((jsonb_typeof(p_scalars->'identifier')='string') OR (jsonb_typeof(p_scalars->'identifier')='null'))) AND (NOT p_scalars ? 'voice' OR ((jsonb_typeof(p_scalars->'voice')='string') OR (jsonb_typeof(p_scalars->'voice')='null')));
WHEN 'NativeArray' THEN RETURN p_fields ? 'items' AND p_scalars='{}'::jsonb;
ELSE RETURN false; END CASE; END $$;
REVOKE ALL ON FUNCTION ops.pdf_native_record_shape(text,jsonb,jsonb) FROM PUBLIC;

CREATE OR REPLACE FUNCTION ops.pdf_companion_field_bytes(p_product text,p_revision text,p_stream text,p_stage boolean DEFAULT false)
RETURNS bytea LANGUAGE plpgsql STABLE SET search_path=pg_catalog,pg_temp AS $$
DECLARE payload_ bytea;
BEGIN
 -- Materialize only the explicitly requested semantic field, never a document envelope.
 IF p_stage THEN SELECT string_agg(body,''::bytea ORDER BY ordinal) INTO payload_ FROM ops.pdf_stage_artifact_part
 WHERE product_id=p_product AND revision_id=p_revision AND stream_id=p_stream;
 ELSE SELECT string_agg(body,''::bytea ORDER BY ordinal) INTO payload_ FROM ops.pdf_artifact_part
 WHERE product_id=p_product AND revision_id=p_revision AND stream_id=p_stream; END IF;
 RETURN COALESCE(payload_,''::bytea);
END $$;
REVOKE ALL ON FUNCTION ops.pdf_companion_field_bytes(text,text,text,boolean) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.pdf_companion_body(p_product text,p_revision text,p_family text,p_local text,p_body jsonb)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE f record; body_ jsonb:=p_body; payload_ bytea;
BEGIN
 IF NOT EXISTS(SELECT FROM ops.pdf_published_revision p JOIN kb.pdf_record_companion c ON c.product_id=p.build_id AND c.revision_id=p.build_id
 WHERE p.build_id=p_product AND p_revision=p_product AND c.family=p_family AND c.local_id=p_local AND c.body=p_body) THEN
 RAISE EXCEPTION 'companion field is not in a published revision'; END IF;
 IF p_family='native_metadata' AND p_body->>'kind'<>'recognition_coverage' THEN
 RAISE EXCEPTION 'metadata value requires the lossless byte reader; SQL supports only typed recognition coverage'; END IF;
 FOR f IN SELECT * FROM kb.pdf_record_companion_field WHERE product_id=p_product AND revision_id=p_revision
 AND family=p_family AND local_id=p_local ORDER BY field_name LOOP
 payload_:=ops.pdf_companion_field_bytes(p_product,p_revision,f.stream_id);
 body_:=body_||jsonb_build_object(f.field_name,CASE WHEN f.scalar_kind='y' THEN convert_from(payload_,'UTF8')::jsonb ELSE to_jsonb(convert_from(payload_,'UTF8')) END);
 END LOOP;
 RETURN body_;
END $$;
REVOKE ALL ON FUNCTION ops.pdf_companion_body(text,text,text,text,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.pdf_companion_body(text,text,text,text,jsonb) TO corpus_sem_reader,corpus_sem_evaluator,corpus_sem_writer;

CREATE OR REPLACE FUNCTION ops.bind_pdf_stage_recipe(p_task bigint,p_attempt bigint,p_holder text,p_recipe bytea)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE run_ ops.run; root_ ops.source_build; digest_ text;
BEGIN
 run_:=ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 SELECT * INTO STRICT root_ FROM ops.source_build WHERE task_id=p_task AND release_id=run_.release_id;
 PERFORM sem.require_execution_operation(run_.release_id,'retain_pdf_stage_recipe');
 PERFORM convert_from(p_recipe,'UTF8')::jsonb;
 IF p_recipe IS NULL OR octet_length(p_recipe)=0 THEN RAISE EXCEPTION 'empty stage recipe'; END IF;
 digest_:=encode(sha256(p_recipe),'hex');
 INSERT INTO kb.source_artifact(artifact_digest,content) VALUES(digest_,p_recipe) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM kb.source_artifact WHERE artifact_digest=digest_ AND content=p_recipe) THEN
 RAISE EXCEPTION 'stage recipe custody conflict'; END IF;
 INSERT INTO ops.pdf_stage_recipe VALUES(p_task,root_.artifact_digest,root_.recipe_digest,digest_,run_.release_id) ON CONFLICT DO NOTHING;
 RETURN digest_;
END $$;
REVOKE ALL ON FUNCTION ops.bind_pdf_stage_recipe(bigint,bigint,text,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.bind_pdf_stage_recipe(bigint,bigint,text,bytea) TO corpus_sem_writer;
CREATE OR REPLACE FUNCTION ops.require_pdf_frozen(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text)
RETURNS ops.pdf_stage_build LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build; job ops.task; run_ ops.run;
BEGIN
 -- Pure immutable-candidate inspection must not block the lease heartbeat.
 SELECT * INTO STRICT job FROM ops.task WHERE id=p_task;
 SELECT * INTO STRICT run_ FROM ops.run WHERE id=job.run_id;
 IF job.attempt IS DISTINCT FROM p_attempt OR job.claimed_by IS DISTINCT FROM p_holder
 OR job.status<>'running' OR job.lease_until IS NULL OR job.lease_until<=clock_timestamp()
 OR run_.sealed OR run_.status NOT IN ('created','running') THEN
 RAISE EXCEPTION 'stale frozen PDF owner' USING ERRCODE='P0004'; END IF;
 SELECT * INTO STRICT b FROM ops.pdf_stage_build WHERE build_id=p_build AND task_id=p_task;
 IF b.release_id IS DISTINCT FROM run_.release_id OR b.state NOT IN ('frozen','published') OR b.attempt IS DISTINCT FROM p_attempt OR b.holder IS DISTINCT FROM p_holder
 OR NOT EXISTS(SELECT FROM ops.pdf_frozen_build WHERE build_id=p_build AND frozen_digest=p_frozen) THEN
 RAISE EXCEPTION 'PDF frozen owner/inventory differs' USING ERRCODE='23514'; END IF;
 RETURN b;
END $$;
CREATE OR REPLACE FUNCTION ops.freeze_pdf_build(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_kind text)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build; f text; state_ bytea:=ops.pdf_identity_fold_start('pdf-frozen-inventory-v1');
 row_ record; payload bytea; count_ bigint:=0; total_ bigint:=0;
BEGIN
 PERFORM ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 SELECT * INTO STRICT b FROM ops.pdf_stage_build WHERE build_id=p_build AND task_id=p_task FOR UPDATE;
 IF b.attempt IS DISTINCT FROM p_attempt OR b.holder IS DISTINCT FROM p_holder OR b.state='abandoned' THEN
 RAISE EXCEPTION 'PDF freeze owner differs' USING ERRCODE='23514'; END IF;
 SELECT frozen_digest INTO f FROM ops.pdf_frozen_build WHERE build_id=p_build;
 IF FOUND THEN IF p_kind IS DISTINCT FROM (SELECT kind FROM ops.pdf_frozen_build WHERE build_id=p_build) THEN RAISE EXCEPTION 'frozen publication kind differs'; END IF; RETURN f; END IF;
 PERFORM sem.require_execution_operation(b.release_id,'freeze_pdf_build');

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_artifact_part t WHERE product_id=p_build ORDER BY product_id,revision_id,stream_id,ordinal LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('artifact_part:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_artifact_stream t WHERE product_id=p_build ORDER BY product_id,revision_id,stream_id LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('artifact_stream:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_companion t WHERE product_id=p_build ORDER BY product_id,revision_id,family,local_id LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('companion:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_companion_field t WHERE product_id=p_build ORDER BY product_id,revision_id,family,local_id,field_name LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('companion_field:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_endpoint t WHERE product_id=p_build ORDER BY product_id,revision_id,relation_id,ordinal LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('endpoint:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_document t WHERE product_id=p_build ORDER BY product_id,revision_id LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('header:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_membership t WHERE product_id=p_build ORDER BY product_id,revision_id,parent_id,field_name,ordinal LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('membership:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_native t WHERE product_id=p_build ORDER BY product_id,revision_id,record_id LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('native:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 FOR row_ IN SELECT to_jsonb(t) body FROM ops.pdf_stage_reference t WHERE product_id=p_build ORDER BY product_id,revision_id,reference_id LOOP
 payload:=convert_to(row_.body::text,'UTF8');
 state_:=ops.pdf_identity_fold_step(state_,count_,convert_to('reference:','UTF8')||sha256(payload));
 count_:=count_+1; total_:=total_+octet_length(payload);
 END LOOP;

 IF NOT EXISTS(SELECT FROM ops.pdf_stage_document WHERE product_id=p_build) THEN
 RAISE EXCEPTION 'PDF freeze has no native document header' USING ERRCODE='23514'; END IF;
 f:=encode(ops.pdf_identity_fold_finish(state_,count_,total_),'hex');
 INSERT INTO ops.pdf_frozen_build VALUES(p_build,f,p_kind);
 UPDATE ops.pdf_stage_build SET state='frozen' WHERE build_id=p_build;
 RETURN f;
END $$;
CREATE OR REPLACE FUNCTION ops.adopt_pdf_companion(p_build text,p_task bigint,p_attempt bigint,p_holder text,
 p_family text,p_local text,p_body jsonb,p_key text,p_ordinal bigint,p_fields jsonb DEFAULT '{}'::jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER
 SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build; endpoint_ jsonb; index_ bigint:=0; input_ jsonb; field_ record; body_ jsonb:=p_body; payload_ bytea; profile_ text; metadata_ json; projection_ jsonb; alternatives_ jsonb; prior_ jsonb; property_ text; item_ jsonb;
BEGIN
 b:=ops.require_pdf_build(p_build,p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(b.release_id,'adopt_pdf_companion_batch');
 IF p_family IS NULL OR p_local IS NULL OR p_local='' OR jsonb_typeof(p_body)<>'object' OR
 octet_length(p_body::text)>65536 THEN RAISE EXCEPTION 'invalid typed PDF companion' USING ERRCODE='23514'; END IF;
 IF p_ordinal IS NULL OR p_ordinal<0 OR
 (p_family='occurrence' AND p_local IS DISTINCT FROM p_body->>'occurrence_id') OR
 (p_family='relation' AND p_local IS DISTINCT FROM p_body->>'relation_id') OR
 (p_family='coverage' AND p_local IS DISTINCT FROM p_body->>'coverage_id') OR
 (p_family IN ('input','mapping_report') AND p_local IS DISTINCT FROM p_ordinal::text) OR
 (p_family='native_metadata' AND p_local IS DISTINCT FROM (p_body->>'kind')||':'||(p_body->>'ordinal')) THEN
 RAISE EXCEPTION 'companion identity/order differs from declared semantic row' USING ERRCODE='23514'; END IF;
 IF jsonb_typeof(p_fields)<>'object' THEN RAISE EXCEPTION 'companion fields must be fixed mapping'; END IF;
 FOR field_ IN SELECT key,value#>>'{}' stream_id FROM jsonb_each(p_fields) LOOP
 IF NOT ((p_family='native_metadata' AND field_.key='value') OR (p_family='occurrence' AND field_.key='text'))
 OR p_body ? field_.key THEN RAISE EXCEPTION 'invalid companion external field'; END IF;
 SELECT encoding_profile INTO STRICT profile_ FROM ops.pdf_stage_artifact_stream
 WHERE product_id=p_build AND revision_id=p_build AND stream_id=field_.stream_id;
 IF profile_ IS DISTINCT FROM (CASE WHEN field_.key='value' THEN 'pdf-companion-json-field-v1' ELSE 'pdf-record-scalar-v1:s' END) THEN
 RAISE EXCEPTION 'companion field encoding differs'; END IF;
 payload_:=ops.pdf_companion_field_bytes(p_build,p_build,field_.stream_id,true);
 IF field_.key='value' THEN metadata_:=convert_from(payload_,'UTF8')::json;
 ELSE body_:=body_||jsonb_build_object(field_.key,to_jsonb(convert_from(payload_,'UTF8'))); END IF;
 END LOOP;
 IF p_family='native_metadata' AND (p_body->>'kind' NOT IN
 ('runtime_report','inline_candidate_pages','derivation_mappings','cell_reports','inline_alignment_reports','recognition_coverage','formula_outcomes')
 OR NOT p_body ? 'ordinal' OR NOT p_fields ? 'value') THEN RAISE EXCEPTION 'invalid native metadata kind' USING ERRCODE='23514'; END IF;
 IF p_family='native_metadata' THEN
 IF p_body-(CASE WHEN p_body->>'kind'='formula_outcomes' THEN ARRAY['kind','ordinal','pointer','outcome','has_diagnostic'] ELSE ARRAY['kind','ordinal','pointer'] END)<>'{}'::jsonb
 OR jsonb_typeof(p_body->'ordinal') IS DISTINCT FROM 'number' OR (p_body->>'ordinal')!~'^[0-9]+$'
 THEN RAISE EXCEPTION 'invalid metadata envelope'; END IF;
 -- The native JSON-schema engine inspects actual values without PostgreSQL's
 -- JSON extraction functions, which reject NUL in any nested string.
 prior_:='{}'::jsonb; alternatives_:='[]'::jsonb;
 FOREACH property_ IN ARRAY ARRAY['pointer','prose_pointer','table_pointer'] LOOP
 IF p_body ? 'pointer' THEN
 item_:=jsonb_build_object('required',jsonb_build_array(property_),'properties',
 prior_||jsonb_build_object(property_,jsonb_build_object('type','string','const',p_body->'pointer')));
 alternatives_:=alternatives_||jsonb_build_array(item_);
 END IF;
 prior_:=prior_||jsonb_build_object(property_,jsonb_build_object('not',jsonb_build_object('type','string')));
 END LOOP;
 projection_:=CASE WHEN p_body ? 'pointer' THEN jsonb_build_object('anyOf',alternatives_)
 ELSE jsonb_build_object('properties',prior_) END;
 IF p_body->>'kind'='formula_outcomes' THEN
 IF jsonb_typeof(p_body->'has_diagnostic') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_body->'outcome') IS DISTINCT FROM 'string'
 THEN RAISE EXCEPTION 'invalid formula health projection'; END IF;
 projection_:=jsonb_build_object('allOf',jsonb_build_array(projection_,
 jsonb_build_object('required',jsonb_build_array('outcome'),'properties',jsonb_build_object('outcome',jsonb_build_object('const',p_body->'outcome'))),
 CASE WHEN p_body->'has_diagnostic'='true'::jsonb THEN jsonb_build_object('required',jsonb_build_array('error'))
 ELSE jsonb_build_object('not',jsonb_build_object('required',jsonb_build_array('error'))) END));
 END IF;
 END IF;

IF p_family='input' THEN
IF jsonb_typeof(body_) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductInput' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(body_) key WHERE key<>ALL(ARRAY['role','task_id','product_key','content_digest'])) OR NOT (body_ ? 'role') OR (body_ ? 'role' AND (jsonb_typeof(body_->'role') IS DISTINCT FROM 'string' OR body_->>'role' NOT IN ('alternative','policy_input','recognition','structural'))) OR NOT (body_ ? 'task_id') OR (body_ ? 'task_id' AND (jsonb_typeof(body_->'task_id') IS DISTINCT FROM 'number' OR body_->>'task_id' !~ '^[0-9]+$')) OR (body_ ? 'task_id' AND (body_->>'task_id')::numeric < 1) OR NOT (body_ ? 'product_key') OR (body_ ? 'product_key' AND (jsonb_typeof(body_->'product_key') IS DISTINCT FROM 'string')) OR NOT (body_ ? 'content_digest') OR (body_ ? 'content_digest' AND (jsonb_typeof(body_->'content_digest') IS DISTINCT FROM 'string')) OR (body_ ? 'content_digest' AND body_->>'content_digest' !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductInput' USING ERRCODE='23514'; END IF;

