IF public.json_matches_schema(('{"additionalProperties":false,"properties":{"pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Pointer","type":"string"},"origin_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Origin Pointer","type":"string"},"source_field":{"enum":["cell_text","text"],"title":"Source Field","type":"string"},"start":{"minimum":0,"title":"Start","type":"integer"},"end":{"minimum":0,"title":"End","type":"integer"},"cell_index":{"minimum":0,"title":"Cell Index","type":"integer"},"kind":{"enum":["native_text_range","table_cell","vector_region_anchor"],"title":"Kind","type":"string"}},"required":["pointer","origin_pointer","source_field","start","end","kind"],"title":"PdfDerivationMapping","type":"object"}'::jsonb || jsonb_build_object('allOf',jsonb_build_array(projection_)))::json,metadata_) IS NOT TRUE THEN RAISE EXCEPTION 'metadata value/schema/projection differs: PdfDerivationMapping' USING ERRCODE='23514'; END IF;
END IF;
IF p_family='native_metadata' AND p_body->>'kind'='cell_reports' THEN
IF public.json_matches_schema(('{"additionalProperties":false,"properties":{"table_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Table Pointer","type":"string"},"cell_index":{"minimum":0,"title":"Cell Index","type":"integer"},"page_no":{"minimum":1,"title":"Page No","type":"integer"},"classification":{"enum":["math","prose","unknown"],"title":"Classification","type":"string"},"basis":{"enum":["native-candidate-intersection","native-math-token","native-rich-reference","native-word-text","ocr-word-text","unresolved-native-evidence"],"title":"Basis","type":"string"},"outcome":{"enum":["failed","not_requested","succeeded","unknown"],"title":"Outcome","type":"string"},"formula_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Formula Pointer","type":"string"},"error":{"title":"Error","type":"string"}},"required":["table_pointer","cell_index","page_no","classification","basis","outcome"],"title":"PdfCellReport","type":"object"}'::jsonb || jsonb_build_object('allOf',jsonb_build_array(projection_)))::json,metadata_) IS NOT TRUE THEN RAISE EXCEPTION 'metadata value/schema/projection differs: PdfCellReport' USING ERRCODE='23514'; END IF;
END IF;
IF p_family='native_metadata' AND p_body->>'kind'='inline_alignment_reports' THEN
IF public.json_matches_schema(('{"additionalProperties":false,"properties":{"page_no":{"minimum":1,"title":"Page No","type":"integer"},"candidate_index":{"minimum":0,"title":"Candidate Index","type":"integer"},"item_pointers":{"items":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"type":"string"},"minItems":1,"title":"Item Pointers","type":"array"},"outcome":{"const":"unresolved","title":"Outcome","type":"string"},"basis":{"enum":["ambiguous-native-items","unmatched-native-text"],"title":"Basis","type":"string"},"detail":{"title":"Detail","type":"string"}},"required":["page_no","candidate_index","item_pointers","outcome","basis","detail"],"title":"PdfInlineAlignmentReport","type":"object"}'::jsonb || jsonb_build_object('allOf',jsonb_build_array(projection_)))::json,metadata_) IS NOT TRUE THEN RAISE EXCEPTION 'metadata value/schema/projection differs: PdfInlineAlignmentReport' USING ERRCODE='23514'; END IF;
END IF;
IF p_family='native_metadata' AND p_body->>'kind'='recognition_coverage' THEN
IF public.json_matches_schema(('{"$defs":{"PdfCellCoverage":{"additionalProperties":false,"properties":{"universe":{"const":"cell","title":"Universe","type":"string"},"policy":{"const":"all-nonempty-selected-cells-v1","title":"Policy","type":"string"},"section_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Section Pointer","type":"string"},"membership":{"enum":["descendants","direct"],"title":"Membership","type":"string"},"outcome":{"enum":["complete","partial","unknown","unsupported"],"title":"Outcome","type":"string"}},"required":["universe","policy","section_pointer","membership","outcome"],"title":"PdfCellCoverage","type":"object"},"PdfDisplayCoverage":{"additionalProperties":false,"properties":{"universe":{"const":"display","title":"Universe","type":"string"},"policy":{"const":"detected-native-display-v1","title":"Policy","type":"string"},"section_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Section Pointer","type":"string"},"membership":{"enum":["descendants","direct"],"title":"Membership","type":"string"},"outcome":{"enum":["complete","partial","unknown","unsupported"],"title":"Outcome","type":"string"}},"required":["universe","policy","section_pointer","membership","outcome"],"title":"PdfDisplayCoverage","type":"object"},"PdfInlineCoverage":{"additionalProperties":false,"properties":{"universe":{"const":"inline","title":"Universe","type":"string"},"policy":{"const":"native-font-token-vector-v2","title":"Policy","type":"string"},"section_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Section Pointer","type":"string"},"membership":{"enum":["descendants","direct"],"title":"Membership","type":"string"},"outcome":{"enum":["complete","partial","unknown","unsupported"],"title":"Outcome","type":"string"}},"required":["universe","policy","section_pointer","membership","outcome"],"title":"PdfInlineCoverage","type":"object"},"PdfOcrInlineCoverage":{"additionalProperties":false,"properties":{"universe":{"const":"inline","title":"Universe","type":"string"},"policy":{"const":"native-font-token-vector-ocr-word-v3","title":"Policy","type":"string"},"section_pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Section Pointer","type":"string"},"membership":{"enum":["descendants","direct"],"title":"Membership","type":"string"},"outcome":{"enum":["complete","partial","unknown","unsupported"],"title":"Outcome","type":"string"}},"required":["universe","policy","section_pointer","membership","outcome"],"title":"PdfOcrInlineCoverage","type":"object"}},"discriminator":{"mapping":{"all-nonempty-selected-cells-v1":"#/$defs/PdfCellCoverage","detected-native-display-v1":"#/$defs/PdfDisplayCoverage","native-font-token-vector-ocr-word-v3":"#/$defs/PdfOcrInlineCoverage","native-font-token-vector-v2":"#/$defs/PdfInlineCoverage"},"propertyName":"policy"},"oneOf":[{"$ref":"#/$defs/PdfDisplayCoverage"},{"$ref":"#/$defs/PdfInlineCoverage"},{"$ref":"#/$defs/PdfCellCoverage"},{"$ref":"#/$defs/PdfOcrInlineCoverage"}]}'::jsonb || jsonb_build_object('allOf',jsonb_build_array(projection_)))::json,metadata_) IS NOT TRUE THEN RAISE EXCEPTION 'metadata value/schema/projection differs: PdfRecognitionCoverage' USING ERRCODE='23514'; END IF;
END IF;
IF p_family='native_metadata' AND p_body->>'kind'='formula_outcomes' THEN
IF public.json_matches_schema(('{"$defs":{"PdfCompanionReference":{"additionalProperties":false,"properties":{"family":{"const":"native_metadata","title":"Family","type":"string"},"local_id":{"title":"Local Id","type":"string"},"task_id":{"minimum":1,"title":"Task Id","type":"integer"},"product_key":{"title":"Product Key","type":"string"},"content_digest":{"allOf":[{"pattern":"^[0-9a-f]{64}$"}],"title":"Content Digest","type":"string"}},"required":["family","local_id","task_id","product_key","content_digest"],"title":"PdfCompanionReference","type":"object"}},"additionalProperties":false,"properties":{"pointer":{"allOf":[{"pattern":"^#(/[^/]+)+$"}],"title":"Pointer","type":"string"},"outcome":{"enum":["failed","not_requested","succeeded","unknown"],"title":"Outcome","type":"string"},"error":{"title":"Error","type":"string"},"diagnostic_ref":{"$ref":"#/$defs/PdfCompanionReference"}},"required":["pointer","outcome"],"title":"PdfFormulaOutcome","type":"object"}'::jsonb || jsonb_build_object('allOf',jsonb_build_array(projection_)))::json,metadata_) IS NOT TRUE THEN RAISE EXCEPTION 'metadata value/schema/projection differs: PdfFormulaOutcome' USING ERRCODE='23514'; END IF;
END IF;
IF p_family='health' THEN IF p_body ? 'conversion' THEN
IF jsonb_typeof(p_body) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfRecordNativeHealth' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(p_body) key WHERE key<>ALL(ARRAY['source_scope','page_start','page_end','conversion','display_coverage','inline_coverage','cell_coverage','issues','formula_outcomes','candidate_policy','cells_policy','inline_scope','cell_scope','inline_membership','cell_membership'])) OR NOT (p_body ? 'source_scope') OR (p_body ? 'source_scope' AND (jsonb_typeof(p_body->'source_scope') IS DISTINCT FROM 'string')) OR (p_body ? 'source_scope' AND p_body->>'source_scope' !~ '^(whole_document|page_range)$') OR (p_body ? 'page_start' AND (jsonb_typeof(p_body->'page_start') IS DISTINCT FROM 'number' OR p_body->>'page_start' !~ '^[0-9]+$')) OR (p_body ? 'page_start' AND (p_body->>'page_start')::numeric < 1) OR (p_body ? 'page_end' AND (jsonb_typeof(p_body->'page_end') IS DISTINCT FROM 'number' OR p_body->>'page_end' !~ '^[0-9]+$')) OR (p_body ? 'page_end' AND (p_body->>'page_end')::numeric < 1) OR NOT (p_body ? 'conversion') OR (p_body ? 'conversion' AND (jsonb_typeof(p_body->'conversion') IS DISTINCT FROM 'string' OR p_body->>'conversion' NOT IN ('failure','partial_success','success'))) OR NOT (p_body ? 'display_coverage') OR (p_body ? 'display_coverage' AND (jsonb_typeof(p_body->'display_coverage') IS DISTINCT FROM 'string' OR p_body->>'display_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (p_body ? 'inline_coverage') OR (p_body ? 'inline_coverage' AND (jsonb_typeof(p_body->'inline_coverage') IS DISTINCT FROM 'string' OR p_body->>'inline_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR NOT (p_body ? 'cell_coverage') OR (p_body ? 'cell_coverage' AND (jsonb_typeof(p_body->'cell_coverage') IS DISTINCT FROM 'string' OR p_body->>'cell_coverage' NOT IN ('complete','partial','unknown','unsupported'))) OR (p_body ? 'issues' AND (jsonb_typeof(p_body->'issues') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'issues') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (p_body ? 'formula_outcomes' AND (jsonb_typeof(p_body->'formula_outcomes') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'formula_outcomes') nested_record WHERE jsonb_typeof(nested_record) IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record) key WHERE key<>ALL(ARRAY['pointer','outcome','error','diagnostic_ref'])) OR NOT (nested_record ? 'pointer') OR (nested_record ? 'pointer' AND (jsonb_typeof(nested_record->'pointer') IS DISTINCT FROM 'string')) OR (nested_record ? 'pointer' AND nested_record->>'pointer' !~ '^#(/[^/]+)+$') OR NOT (nested_record ? 'outcome') OR (nested_record ? 'outcome' AND (jsonb_typeof(nested_record->'outcome') IS DISTINCT FROM 'string' OR nested_record->>'outcome' NOT IN ('failed','not_requested','succeeded','unknown'))) OR (nested_record ? 'error' AND (jsonb_typeof(nested_record->'error') IS DISTINCT FROM 'string')) OR (nested_record ? 'diagnostic_ref' AND (jsonb_typeof(nested_record->'diagnostic_ref') IS DISTINCT FROM 'object' OR (EXISTS(SELECT FROM jsonb_object_keys(nested_record->'diagnostic_ref') key WHERE key<>ALL(ARRAY['family','local_id','task_id','product_key','content_digest'])) OR NOT (nested_record->'diagnostic_ref' ? 'family') OR (nested_record->'diagnostic_ref' ? 'family' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'family') IS DISTINCT FROM 'string')) OR nested_record->'diagnostic_ref'->>'family' IS DISTINCT FROM 'native_metadata' OR NOT (nested_record->'diagnostic_ref' ? 'local_id') OR (nested_record->'diagnostic_ref' ? 'local_id' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'local_id') IS DISTINCT FROM 'string')) OR NOT (nested_record->'diagnostic_ref' ? 'task_id') OR (nested_record->'diagnostic_ref' ? 'task_id' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'task_id') IS DISTINCT FROM 'number' OR nested_record->'diagnostic_ref'->>'task_id' !~ '^[0-9]+$')) OR (nested_record->'diagnostic_ref' ? 'task_id' AND (nested_record->'diagnostic_ref'->>'task_id')::numeric < 1) OR NOT (nested_record->'diagnostic_ref' ? 'product_key') OR (nested_record->'diagnostic_ref' ? 'product_key' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'product_key') IS DISTINCT FROM 'string')) OR NOT (nested_record->'diagnostic_ref' ? 'content_digest') OR (nested_record->'diagnostic_ref' ? 'content_digest' AND (jsonb_typeof(nested_record->'diagnostic_ref'->'content_digest') IS DISTINCT FROM 'string')) OR (nested_record->'diagnostic_ref' ? 'content_digest' AND nested_record->'diagnostic_ref'->>'content_digest' !~ '^[0-9a-f]{64}$')))))))) OR (p_body ? 'candidate_policy' AND (jsonb_typeof(p_body->'candidate_policy') IS DISTINCT FROM 'string' OR p_body->>'candidate_policy' NOT IN ('native-font-token-vector-ocr-word-v3','native-font-token-vector-v2','native-math-font-or-token-v1'))) OR (p_body ? 'cells_policy' AND (jsonb_typeof(p_body->'cells_policy') IS DISTINCT FROM 'string' OR p_body->>'cells_policy' NOT IN ('all-nonempty-selected-cells-v1'))) OR (p_body ? 'inline_scope' AND (jsonb_typeof(p_body->'inline_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'inline_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (p_body ? 'inline_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(p_body->'inline_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (p_body ? 'cell_scope' AND (jsonb_typeof(p_body->'cell_scope') IS DISTINCT FROM 'array' OR EXISTS(SELECT FROM jsonb_array_elements(p_body->'cell_scope') element WHERE jsonb_typeof(element) IS DISTINCT FROM 'string'))) OR (p_body ? 'cell_scope' AND EXISTS(SELECT FROM jsonb_array_elements_text(p_body->'cell_scope') element WHERE element !~ '^#(/[^/]+)+$')) OR (p_body ? 'inline_membership' AND (jsonb_typeof(p_body->'inline_membership') IS DISTINCT FROM 'string' OR p_body->>'inline_membership' NOT IN ('descendants','direct'))) OR (p_body ? 'cell_membership' AND (jsonb_typeof(p_body->'cell_membership') IS DISTINCT FROM 'string' OR p_body->>'cell_membership' NOT IN ('descendants','direct'))) THEN RAISE EXCEPTION 'parsing record shape differs: PdfRecordNativeHealth' USING ERRCODE='23514'; END IF;

 ELSE IF jsonb_typeof(p_body) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'parsing record must be an object: PdfProductHealth' USING ERRCODE='23514'; END IF;
IF EXISTS(SELECT FROM jsonb_object_keys(p_body) key WHERE key<>ALL(ARRAY['execution_outcome','mapping_outcome','source_fidelity','validation_report'])) OR NOT (p_body ? 'execution_outcome') OR (p_body ? 'execution_outcome' AND (jsonb_typeof(p_body->'execution_outcome') IS DISTINCT FROM 'string' OR p_body->>'execution_outcome' NOT IN ('failed','partial','succeeded','unknown','unsupported'))) OR NOT (p_body ? 'mapping_outcome') OR (p_body ? 'mapping_outcome' AND (jsonb_typeof(p_body->'mapping_outcome') IS DISTINCT FROM 'string' OR p_body->>'mapping_outcome' NOT IN ('coarse','partial','unknown','unsupported'))) OR NOT (p_body ? 'source_fidelity') OR (p_body ? 'source_fidelity' AND (jsonb_typeof(p_body->'source_fidelity') IS DISTINCT FROM 'string' OR p_body->>'source_fidelity' NOT IN ('conflict','unassessed','unknown'))) OR NOT (p_body ? 'validation_report') OR (p_body ? 'validation_report' AND (jsonb_typeof(p_body->'validation_report') IS DISTINCT FROM 'string')) THEN RAISE EXCEPTION 'parsing record shape differs: PdfProductHealth' USING ERRCODE='23514'; END IF;

 END IF; END IF;
 INSERT INTO ops.pdf_stage_companion VALUES(p_build,p_build,p_family,p_local,p_body,p_ordinal) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_companion WHERE product_id=p_build AND family=p_family AND local_id=p_local AND body=p_body AND ordinal=p_ordinal) THEN
 RAISE EXCEPTION 'changed companion duplicate' USING ERRCODE='23514'; END IF;
 FOR field_ IN SELECT key,value#>>'{}' stream_id FROM jsonb_each(p_fields) LOOP
 INSERT INTO ops.pdf_stage_companion_field VALUES(p_build,p_build,p_family,p_local,field_.key,field_.stream_id,
 CASE WHEN field_.key='value' THEN 'y' ELSE 's' END) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_companion_field WHERE product_id=p_build AND family=p_family AND local_id=p_local
 AND field_name=field_.key AND stream_id=field_.stream_id) THEN RAISE EXCEPTION 'changed companion field duplicate'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM ops.pdf_stage_companion_field WHERE product_id=p_build AND family=p_family AND local_id=p_local)
 <>(SELECT count(*) FROM jsonb_object_keys(p_fields)) THEN RAISE EXCEPTION 'changed companion field inventory'; END IF;
 IF p_family='relation' THEN
 IF jsonb_typeof(p_body->'endpoints')<>'array' OR jsonb_array_length(p_body->'endpoints')=0 THEN
 RAISE EXCEPTION 'relation lacks independent endpoints' USING ERRCODE='23514'; END IF;
 FOR endpoint_ IN SELECT value FROM jsonb_array_elements(p_body->'endpoints') LOOP
 IF endpoint_ ? 'input_index' THEN
 SELECT body INTO STRICT input_ FROM ops.pdf_stage_companion WHERE product_id=p_build
 AND family='input' AND local_id=endpoint_->>'input_index';
 ELSE input_:=jsonb_build_object('task_id',0,'product_key','@self','content_digest','@self'); END IF;
 INSERT INTO ops.pdf_stage_endpoint VALUES(p_build,p_build,p_local,index_,(input_->>'task_id')::bigint,
 input_->>'product_key',input_->>'content_digest',endpoint_->>'occurrence_id',endpoint_->>'role') ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_endpoint WHERE product_id=p_build AND relation_id=p_local AND ordinal=index_
 AND occurrence_id=endpoint_->>'occurrence_id' AND role=endpoint_->>'role'
 AND target_task_id=(input_->>'task_id')::bigint AND target_content_digest=input_->>'content_digest') THEN
 RAISE EXCEPTION 'changed companion endpoint duplicate' USING ERRCODE='23514'; END IF;
 index_:=index_+1;
 END LOOP; END IF;
END $$;
CREATE OR REPLACE FUNCTION ops.pdf_reference_bytes_equal(p_product text,p_revision text,p_left text,p_left_stream text,p_right text,p_right_stream text)
RETURNS boolean LANGUAGE sql STABLE SET search_path=pg_catalog,pg_temp AS $$
 SELECT COALESCE(CASE WHEN p_left_stream IS NULL THEN octet_length(convert_to(p_left,'UTF8')) ELSE l.byte_length END
 = CASE WHEN p_right_stream IS NULL THEN octet_length(convert_to(p_right,'UTF8')) ELSE r.byte_length END
 AND CASE WHEN p_left_stream IS NULL THEN encode(ops.pdf_identity_byte_root(convert_to(p_left,'UTF8')),'hex') ELSE l.byte_root END
 = CASE WHEN p_right_stream IS NULL THEN encode(ops.pdf_identity_byte_root(convert_to(p_right,'UTF8')),'hex') ELSE r.byte_root END,false)
 FROM (SELECT 1) one_ LEFT JOIN ops.pdf_artifact_stream l ON l.product_id=p_product AND l.revision_id=p_revision AND l.stream_id=p_left_stream
 LEFT JOIN ops.pdf_artifact_stream r ON r.product_id=p_product AND r.revision_id=p_revision AND r.stream_id=p_right_stream
$$;
REVOKE ALL ON FUNCTION ops.pdf_reference_bytes_equal(text,text,text,text,text,text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION ops.prepare_pdf_build(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build;
BEGIN b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 PERFORM sem.require_execution_operation(b.release_id,'prepare_pdf_build');
INSERT INTO ops.pdf_record_document(product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id) SELECT product_id,revision_id,release_id,source_digest,mapping_profile,contract_version,native_schema_digest,root_id FROM ops.pdf_stage_document s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO ops.pdf_artifact_stream(product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile) SELECT product_id,revision_id,stream_id,byte_length,serialization_sha256,byte_root,encoding_profile FROM ops.pdf_stage_artifact_stream s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO kb.pdf_record_native(product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json) SELECT product_id,revision_id,record_id,native_type,family,native_address,native_address_stream_id,scalars_json,structure_json FROM ops.pdf_stage_native s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO kb.pdf_record_membership(product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id) SELECT product_id,revision_id,parent_id,field_name,ordinal,member_key,member_key_stream_id,value_kind,record_id,scalar_json,stream_id FROM ops.pdf_stage_membership s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO kb.pdf_record_reference(product_id,revision_id,reference_id,source_id,field_name,native_pointer,native_pointer_stream_id,target_id) SELECT s.product_id,s.revision_id,s.reference_id,s.source_id,s.field_name,s.native_pointer,s.native_pointer_stream_id,COALESCE(s.target_id,(SELECT n.record_id FROM kb.pdf_record_native n WHERE n.product_id=p_build AND ((s.field_name NOT IN ('source_cell_id','target_cell_id') AND ops.pdf_reference_bytes_equal(p_build,p_build,n.native_address,n.native_address_stream_id,s.native_pointer,s.native_pointer_stream_id)) OR (s.field_name IN ('source_cell_id','target_cell_id') AND n.native_type='GraphCell' AND n.scalars_json->>'cell_id'=s.native_pointer AND regexp_replace(n.native_address,'/cells/[0-9]+$','')=regexp_replace((SELECT source.native_address FROM kb.pdf_record_native source WHERE source.product_id=p_build AND source.record_id=s.source_id),'/links/[0-9]+$',''))))) FROM ops.pdf_stage_reference s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO ops.pdf_artifact_part(product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest) SELECT product_id,revision_id,stream_id,ordinal,byte_offset,byte_length,body,sha256_digest FROM ops.pdf_stage_artifact_part s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO kb.pdf_record_companion(product_id,revision_id,family,local_id,body,ordinal) SELECT product_id,revision_id,family,local_id,body,ordinal FROM ops.pdf_stage_companion s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO kb.pdf_record_endpoint(product_id,revision_id,relation_id,ordinal,target_task_id,target_product_key,target_content_digest,occurrence_id,role) SELECT product_id,revision_id,relation_id,ordinal,target_task_id,target_product_key,target_content_digest,occurrence_id,role FROM ops.pdf_stage_endpoint s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
INSERT INTO kb.pdf_record_companion_field(product_id,revision_id,family,local_id,field_name,stream_id,scalar_kind) SELECT product_id,revision_id,family,local_id,field_name,stream_id,scalar_kind FROM ops.pdf_stage_companion_field s WHERE s.product_id=p_build ON CONFLICT DO NOTHING;
 PERFORM ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen); END $$;
CREATE OR REPLACE FUNCTION ops.read_pdf_published_revision(p_task bigint,p_key text,p_digest text)
RETURNS SETOF ops.pdf_published_revision LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT p.* FROM ops.pdf_published_revision p JOIN ops.pdf_stage_build b USING(build_id)
 WHERE p.task_id=p_task AND p.product_key=p_key AND p.logical_digest=p_digest AND b.state='published'
$$;

CREATE OR REPLACE FUNCTION ops.read_pdf_frozen_rows(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text,
 p_family text,p_after jsonb,p_limit integer)
RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $reader$
DECLARE published ops.pdf_stage_build; p_filters jsonb:='{}'::jsonb;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 OR p_filters IS NULL OR
 jsonb_typeof(p_filters)<>'object' OR (p_after IS NOT NULL AND jsonb_typeof(p_after)<>'array') THEN
 RAISE EXCEPTION 'invalid published record page' USING ERRCODE='22023'; END IF;
 published:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 CASE p_family
WHEN 'header' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY[]::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.product_id)) FROM ops.pdf_record_document r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND (true) AND (p_after IS NULL OR ROW(r.product_id)>ROW((p_after->>0)))
 ORDER BY r.product_id LIMIT p_limit;
WHEN 'native' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['record_id','native_address']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.record_id)) FROM kb.pdf_record_native r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'record_id' OR r.record_id=p_filters->>'record_id') AND (NOT p_filters ? 'native_address' OR r.native_address=p_filters->>'native_address')) AND (p_after IS NULL OR ROW(r.record_id)>ROW((p_after->>0)))
 ORDER BY r.record_id LIMIT p_limit;
WHEN 'membership' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['parent_id','field_name']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.parent_id,r.field_name,r.ordinal)) FROM kb.pdf_record_membership r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'parent_id' OR r.parent_id=p_filters->>'parent_id') AND (NOT p_filters ? 'field_name' OR r.field_name=p_filters->>'field_name')) AND (p_after IS NULL OR ROW(r.parent_id,r.field_name,r.ordinal)>ROW((p_after->>0),(p_after->>1),(p_after->>2)::bigint))
 ORDER BY r.parent_id,r.field_name,r.ordinal NULLS LAST LIMIT p_limit;
WHEN 'reference' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['source_id','target_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.reference_id)) FROM kb.pdf_record_reference r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'source_id' OR r.source_id=p_filters->>'source_id') AND (NOT p_filters ? 'target_id' OR r.target_id=p_filters->>'target_id')) AND (p_after IS NULL OR ROW(r.reference_id)>ROW((p_after->>0)))
 ORDER BY r.reference_id LIMIT p_limit;
WHEN 'artifact_stream' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['stream_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.stream_id)) FROM ops.pdf_artifact_stream r
 WHERE (r.encoding_profile LIKE 'pdf-record-scalar-v1:%' OR r.encoding_profile='pdf-record-native-json-v1') AND NOT EXISTS(SELECT FROM kb.pdf_record_companion_field cf WHERE cf.product_id=r.product_id AND cf.revision_id=r.revision_id AND cf.stream_id=r.stream_id) AND r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'stream_id' OR r.stream_id=p_filters->>'stream_id')) AND (p_after IS NULL OR ROW(r.stream_id)>ROW((p_after->>0)))
 ORDER BY r.stream_id LIMIT p_limit;
WHEN 'artifact_part' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['stream_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.stream_id,r.ordinal)) FROM ops.pdf_artifact_part r
 WHERE EXISTS(SELECT FROM ops.pdf_artifact_stream s WHERE s.product_id=r.product_id AND s.revision_id=r.revision_id AND s.stream_id=r.stream_id AND (s.encoding_profile LIKE 'pdf-record-scalar-v1:%' OR s.encoding_profile='pdf-record-native-json-v1')) AND NOT EXISTS(SELECT FROM kb.pdf_record_companion_field cf WHERE cf.product_id=r.product_id AND cf.revision_id=r.revision_id AND cf.stream_id=r.stream_id) AND r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'stream_id' OR r.stream_id=p_filters->>'stream_id')) AND (p_after IS NULL OR ROW(r.stream_id,r.ordinal)>ROW((p_after->>0),(p_after->>1)::bigint))
 ORDER BY r.stream_id,r.ordinal NULLS LAST LIMIT p_limit;
WHEN 'companion' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['family','local_id','kind','pointer']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.family,r.ordinal,r.local_id))||jsonb_build_object('_fields',COALESCE((SELECT jsonb_agg(jsonb_build_object('field_name',cf.field_name,'stream_id',cf.stream_id,'scalar_kind',cf.scalar_kind) ORDER BY cf.field_name) FROM kb.pdf_record_companion_field cf WHERE cf.product_id=r.product_id AND cf.revision_id=r.revision_id AND cf.family=r.family AND cf.local_id=r.local_id),'[]'::jsonb)) FROM kb.pdf_record_companion r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'family' OR r.family=p_filters->>'family') AND (NOT p_filters ? 'local_id' OR r.local_id=p_filters->>'local_id') AND (NOT p_filters ? 'kind' OR r.body->'kind'=p_filters->'kind') AND (NOT p_filters ? 'pointer' OR r.body->'pointer'=p_filters->'pointer')) AND (p_after IS NULL OR ((p_after->1='null'::jsonb AND (r.family>p_after->>0 OR r.family=p_after->>0 AND r.ordinal IS NULL AND r.local_id>p_after->>2)) OR (p_after->1<>'null'::jsonb AND (ROW(r.family,r.ordinal,r.local_id)>ROW((p_after->>0),(p_after->>1)::bigint,(p_after->>2)) OR r.family=p_after->>0 AND r.ordinal IS NULL))))
 ORDER BY r.family,r.ordinal NULLS LAST,r.local_id LIMIT p_limit;
WHEN 'companion_field' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['family','local_id','field_name']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.family,r.local_id,r.field_name)) FROM kb.pdf_record_companion_field r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'family' OR r.family=p_filters->>'family') AND (NOT p_filters ? 'local_id' OR r.local_id=p_filters->>'local_id') AND (NOT p_filters ? 'field_name' OR r.field_name=p_filters->>'field_name')) AND (p_after IS NULL OR ROW(r.family,r.local_id,r.field_name)>ROW((p_after->>0),(p_after->>1),(p_after->>2)))
 ORDER BY r.family,r.local_id,r.field_name LIMIT p_limit;
WHEN 'endpoint' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['relation_id','occurrence_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.relation_id,r.ordinal)) FROM kb.pdf_record_endpoint r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'relation_id' OR r.relation_id=p_filters->>'relation_id') AND (NOT p_filters ? 'occurrence_id' OR r.occurrence_id=p_filters->>'occurrence_id')) AND (p_after IS NULL OR ROW(r.relation_id,r.ordinal)>ROW((p_after->>0),(p_after->>1)::bigint))
 ORDER BY r.relation_id,r.ordinal NULLS LAST LIMIT p_limit;
 ELSE RAISE EXCEPTION 'unknown published record family' USING ERRCODE='22023';
 END CASE;
END $reader$;

CREATE OR REPLACE FUNCTION ops.adopt_pdf_access(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text,p_family text,p_body jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build;
BEGIN b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 IF b.state<>'frozen' THEN RAISE EXCEPTION 'published PDF projection immutable'; END IF;
 IF p_family='access' THEN
 INSERT INTO kb.pdf_record_access SELECT (jsonb_populate_record(NULL::kb.pdf_record_access,p_body||jsonb_build_object('product_id',p_build,'revision_id',p_build))).* ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM kb.pdf_record_access r WHERE product_id=p_build AND r.pointer=p_body->>'pointer'
 AND to_jsonb(r)-'product_id'-'revision_id'=p_body) THEN RAISE EXCEPTION 'changed access projection'; END IF;
 ELSIF p_family='region' THEN
 INSERT INTO kb.pdf_record_region SELECT (jsonb_populate_record(NULL::kb.pdf_record_region,p_body||jsonb_build_object('product_id',p_build,'revision_id',p_build))).* ON CONFLICT DO NOTHING;
 ELSE RAISE EXCEPTION 'invalid projection family'; END IF;
END $$;
CREATE OR REPLACE FUNCTION ops.adopt_pdf_access_batch(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text,p_rows jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE row_ jsonb;
BEGIN
 IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows)>128 OR octet_length(p_rows::text)>16777216 THEN
 RAISE EXCEPTION 'access projection batch exceeds profile'; END IF;
 FOR row_ IN SELECT value FROM jsonb_array_elements(p_rows) LOOP
 PERFORM ops.adopt_pdf_access(p_build,p_task,p_attempt,p_holder,p_frozen,row_->>'family',row_->'body');
 END LOOP;
END $$;
CREATE OR REPLACE FUNCTION ops.record_pdf_native_validation(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text,p_passed boolean)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build; contract_ text;
BEGIN
 b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 PERFORM sem.require_execution_operation(b.release_id,'validate_pdf_build');
 SELECT encode(sha256(content),'hex') INTO STRICT contract_ FROM sem.input WHERE release_id=b.release_id
 AND input_kind='dependency' AND input_name='execution/implementation/pdf/publication.py';
 INSERT INTO ops.pdf_native_validation VALUES(p_build,p_frozen,contract_,p_passed) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT FROM ops.pdf_native_validation WHERE build_id=p_build AND frozen_digest=p_frozen AND contract_digest=contract_ AND passed=p_passed) THEN
 RAISE EXCEPTION 'native callback outcome conflicts for immutable premises'; END IF;
END $$;
CREATE OR REPLACE FUNCTION ops.validate_pdf_build(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text)
RETURNS SETOF ops.pdf_build_validation LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build; stream_ record; logical_ text; contract_ text;
BEGIN
 b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 PERFORM sem.require_execution_operation(b.release_id,'validate_pdf_build');
 IF NOT EXISTS(SELECT FROM ops.pdf_native_validation v JOIN sem.input i ON i.release_id=b.release_id AND i.input_kind='dependency' AND i.input_name='execution/implementation/pdf/publication.py' AND v.contract_digest=encode(sha256(i.content),'hex') WHERE v.build_id=p_build AND v.frozen_digest=p_frozen AND v.passed) THEN RAISE EXCEPTION 'native callback conformance outcome missing or stale' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n WHERE n.product_id=p_build AND
 ops.pdf_native_record_shape(n.native_type,n.scalars_json,n.structure_json->'fields') IS NOT TRUE) THEN
 RAISE EXCEPTION 'native schema field/required/primitive constraint differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n WHERE n.product_id=p_build AND
 (jsonb_typeof(n.structure_json->'fields') IS DISTINCT FROM 'object' OR
 EXISTS(SELECT FROM jsonb_each(n.structure_json->'fields') f WHERE f.value->>'kind' NOT IN ('object','array','map','parts')) OR
 EXISTS(SELECT FROM jsonb_object_keys(n.scalars_json) k WHERE n.structure_json->'fields' ? k))) THEN
 RAISE EXCEPTION 'invalid native field decomposition' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_membership m LEFT JOIN kb.pdf_record_native n ON n.product_id=p_build AND n.record_id=m.parent_id
 WHERE m.product_id=p_build AND (n.record_id IS NULL OR n.structure_json->'fields'->m.field_name->>'kind' NOT IN ('array','map'))) THEN
 RAISE EXCEPTION 'membership outside declared collection' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n WHERE n.product_id=p_build AND n.scalars_json ? 'self_ref'
 GROUP BY n.scalars_json->>'self_ref' HAVING count(*)<>1) THEN
 RAISE EXCEPTION 'native self-reference is not unique' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n LEFT JOIN kb.pdf_record_reference r ON r.product_id=p_build AND r.source_id=n.record_id AND r.field_name='$ref'
 WHERE n.product_id=p_build AND n.native_type IN ('RefItem','FineRef') AND
 (r.reference_id IS NULL OR NOT ops.pdf_reference_bytes_equal(p_build,p_build,r.native_pointer,r.native_pointer_stream_id,n.scalars_json->>'$ref',n.structure_json->'fields'->'$ref'->>'stream_id'))) THEN
 RAISE EXCEPTION 'native reference index does not correspond to supplied spelling' USING ERRCODE='23514'; END IF;
 IF EXISTS(WITH RECURSIVE edges AS (
 SELECT n.record_id parent_id,(f.value->>'target') child_id FROM kb.pdf_record_native n
 CROSS JOIN LATERAL jsonb_each(n.structure_json->'fields') f WHERE n.product_id=p_build AND f.value->>'kind'='object'
 UNION ALL SELECT parent_id,record_id FROM kb.pdf_record_membership WHERE product_id=p_build AND value_kind='record'
 ), paths AS (
 SELECT parent_id,child_id,ARRAY[parent_id,child_id] path,parent_id=child_id cyclic FROM edges
 UNION ALL SELECT p.parent_id,e.child_id,p.path||e.child_id,e.child_id=ANY(p.path) FROM paths p JOIN edges e ON e.parent_id=p.child_id WHERE NOT p.cyclic
 ) SELECT FROM paths WHERE cyclic) THEN RAISE EXCEPTION 'native containment cycle' USING ERRCODE='23514'; END IF;
 IF EXISTS(WITH owner_edges AS (
 SELECT n.record_id parent_id,f.value->>'target' child_id FROM kb.pdf_record_native n CROSS JOIN LATERAL jsonb_each(n.structure_json->'fields') f
 WHERE n.product_id=p_build AND f.value->>'kind'='object'
 UNION ALL SELECT parent_id,record_id FROM kb.pdf_record_membership WHERE product_id=p_build AND value_kind='record'
 ) SELECT FROM kb.pdf_record_native n LEFT JOIN owner_edges e ON e.child_id=n.record_id
 WHERE n.product_id=p_build GROUP BY n.record_id HAVING count(e.parent_id)<>CASE WHEN n.record_id=(SELECT root_id FROM ops.pdf_record_document WHERE product_id=p_build) THEN 0 ELSE 1 END) THEN
 RAISE EXCEPTION 'native orphan or repeated containment owner' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_access parent JOIN kb.pdf_record_access child ON
 child.product_id=parent.product_id AND child.parent_pointer=parent.pointer
 WHERE parent.product_id=p_build AND NOT EXISTS(SELECT FROM jsonb_array_elements(COALESCE(parent.native_json->'children','[]')) c WHERE c->>'$ref'=child.pointer))
 OR EXISTS(SELECT FROM kb.pdf_record_access parent CROSS JOIN LATERAL jsonb_array_elements(COALESCE(parent.native_json->'children','[]')) c
 LEFT JOIN kb.pdf_record_access child ON child.product_id=p_build AND child.pointer=c->>'$ref'
 WHERE parent.product_id=p_build AND (child.pointer IS NULL OR child.parent_pointer IS DISTINCT FROM parent.pointer)) THEN
 RAISE EXCEPTION 'native parent/child backpointer differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n CROSS JOIN LATERAL jsonb_each(n.structure_json->'fields') f
 LEFT JOIN kb.pdf_record_native target ON target.product_id=p_build AND target.record_id=f.value->>'target'
 WHERE n.product_id=p_build AND f.value->>'kind'='object' AND target.record_id IS NULL) THEN
 RAISE EXCEPTION 'missing native object target' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n CROSS JOIN LATERAL jsonb_each(n.structure_json->'fields') f
 LEFT JOIN LATERAL (SELECT count(*) count_,min(ordinal) min_,max(ordinal) max_ FROM kb.pdf_record_membership m
 WHERE m.product_id=p_build AND m.parent_id=n.record_id AND m.field_name=f.key) members ON true
 WHERE n.product_id=p_build AND f.value->>'kind' IN ('array','map') AND
 (members.count_<>(f.value->>'length')::bigint OR (members.count_>0 AND (members.min_<>0 OR members.max_<>members.count_-1)))) THEN
 RAISE EXCEPTION 'native ordered membership incomplete' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_native n LEFT JOIN ops.pdf_artifact_stream a ON a.product_id=p_build AND a.stream_id=n.native_address_stream_id
 WHERE n.product_id=p_build GROUP BY COALESCE(a.byte_length,octet_length(convert_to(n.native_address,'UTF8'))),
 COALESCE(a.byte_root,encode(ops.pdf_identity_byte_root(convert_to(n.native_address,'UTF8')),'hex')) HAVING count(*)>1) THEN
 RAISE EXCEPTION 'duplicate native address including overflow representation' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_membership m LEFT JOIN ops.pdf_artifact_stream s ON s.product_id=p_build AND s.stream_id=m.member_key_stream_id
 WHERE m.product_id=p_build AND (m.member_key IS NOT NULL OR m.member_key_stream_id IS NOT NULL)
 GROUP BY m.parent_id,m.field_name,COALESCE(s.byte_length,octet_length(convert_to(m.member_key,'UTF8'))),
 COALESCE(s.byte_root,encode(ops.pdf_identity_byte_root(convert_to(m.member_key,'UTF8')),'hex')) HAVING count(*)>1) THEN
 RAISE EXCEPTION 'duplicate native map key including overflow representation' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_reference r LEFT JOIN kb.pdf_record_native n
 ON n.product_id=p_build AND n.record_id=r.target_id WHERE r.product_id=p_build AND
 (n.record_id IS NULL OR (r.native_pointer IS NOT NULL AND r.field_name NOT IN ('source_cell_id','target_cell_id') AND NOT ops.pdf_reference_bytes_equal(p_build,p_build,n.native_address,n.native_address_stream_id,r.native_pointer,r.native_pointer_stream_id)))) THEN
 RAISE EXCEPTION 'native reference/address target differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_companion c LEFT JOIN ops.pdf_product input_ ON
 input_.task_id=(c.body->>'task_id')::bigint AND input_.product_key=c.body->>'product_key' AND input_.content_digest=c.body->>'content_digest'
 LEFT JOIN ops.task task_ ON task_.id=input_.task_id LEFT JOIN ops.run run_ ON run_.id=task_.run_id
 WHERE c.product_id=p_build AND c.family='input' AND
 (input_.task_id IS NULL OR input_.artifact_digest IS DISTINCT FROM b.source_digest OR
 run_.project_id IS DISTINCT FROM (SELECT project_id FROM ops.run WHERE id=b.run_id))) THEN
 RAISE EXCEPTION 'PDF input outside exact admitted source/project custody' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_companion c CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.body->'supports','[]')) support
 WHERE c.product_id=p_build AND c.family='coverage' AND NOT EXISTS(SELECT FROM kb.pdf_record_companion i
 WHERE i.product_id=p_build AND i.family='input' AND i.local_id=support->>'input_index')) THEN
 RAISE EXCEPTION 'coverage support references missing input' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_companion o LEFT JOIN kb.pdf_record_access a ON
 a.product_id=p_build AND a.pointer=o.body->>'pointer' WHERE o.product_id=p_build AND o.family='occurrence'
 AND o.body->>'address_space' IN ('native_item','selected_item','native_cell') AND (a.pointer IS NULL OR
 (o.body ? 'cell_index' AND (o.body->>'cell_index')::bigint>=GREATEST(
 jsonb_array_length(COALESCE(a.native_json->'data'->'table_cells','[]')),
 jsonb_array_length(COALESCE(a.native_json->'meta'->'tabular_chart'->'chart_data'->'table_cells','[]')))))) THEN
 RAISE EXCEPTION 'companion occurrence outside native item/cell inventory' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_endpoint e WHERE e.product_id=p_build AND
 ((e.target_task_id=0 AND NOT EXISTS(SELECT FROM kb.pdf_record_companion o WHERE o.product_id=p_build AND o.family='occurrence' AND o.local_id=e.occurrence_id)) OR
 (e.target_task_id<>0 AND NOT EXISTS(SELECT FROM ops.pdf_product p WHERE p.task_id=e.target_task_id AND p.product_key=e.target_product_key AND p.content_digest=e.target_content_digest AND (EXISTS(SELECT FROM kb.pdf_occurrence o WHERE o.task_id=p.task_id AND o.product_key=p.product_key AND o.occurrence_id=e.occurrence_id) OR EXISTS(SELECT FROM ops.pdf_published_revision pr JOIN kb.pdf_record_companion c ON c.product_id=pr.build_id WHERE pr.task_id=p.task_id AND pr.product_key=p.product_key AND pr.logical_digest=p.content_digest AND c.family='occurrence' AND c.local_id=e.occurrence_id)))))) THEN
 RAISE EXCEPTION 'companion endpoint outside admitted occurrence inventory' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_companion c WHERE c.product_id=p_build AND c.family='native_metadata'
 AND (c.body ? 'value' OR NOT EXISTS(SELECT FROM kb.pdf_record_companion_field f WHERE f.product_id=c.product_id AND f.revision_id=c.revision_id
 AND f.family=c.family AND f.local_id=c.local_id AND f.field_name='value'))) THEN RAISE EXCEPTION 'metadata value has no governed byte field'; END IF;
 IF EXISTS(SELECT FROM kb.pdf_record_companion_field f JOIN kb.pdf_record_companion c USING(product_id,revision_id,family,local_id)
 JOIN ops.pdf_artifact_stream a USING(product_id,revision_id,stream_id) WHERE f.product_id=p_build
 AND (c.body ? f.field_name OR a.encoding_profile IS DISTINCT FROM CASE WHEN f.field_name='value' THEN 'pdf-companion-json-field-v1' ELSE 'pdf-record-scalar-v1:s' END))
 THEN RAISE EXCEPTION 'invalid final companion field'; END IF;
 FOR stream_ IN SELECT stream_id FROM ops.pdf_artifact_stream WHERE product_id=p_build LOOP
 PERFORM ops.pdf_identity_verify_artifact(p_build,p_build,stream_.stream_id); END LOOP;
 IF EXISTS(SELECT FROM kb.pdf_record_native n WHERE n.product_id=p_build AND n.native_type IN
 ('TextItem','ListItem','SectionHeaderItem','FormulaItem','CodeItem','GroupItem','ListGroup','PictureItem','TableItem')
 AND n.scalars_json ? 'self_ref' AND NOT EXISTS(SELECT FROM kb.pdf_record_access a WHERE a.product_id=p_build
 AND a.pointer=n.scalars_json->>'self_ref')) THEN RAISE EXCEPTION 'native access inventory incomplete' USING ERRCODE='23514'; END IF;
 PERFORM ops.pdf_check_access_correspondence(p_build);
 logical_:=ops.pdf_record_logical_identity(p_build,p_build);
 PERFORM ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 SELECT encode(sha256(content),'hex') INTO STRICT contract_ FROM sem.input WHERE release_id=b.release_id
 AND input_kind='dependency' AND input_name='execution/schema/pdf_products';
 INSERT INTO ops.pdf_build_validation SELECT p_build,p_frozen,logical_,contract_,v.passed,v.contract_digest FROM ops.pdf_native_validation v JOIN sem.input i ON i.release_id=b.release_id AND i.input_kind='dependency' AND i.input_name='execution/implementation/pdf/publication.py' AND v.contract_digest=encode(sha256(i.content),'hex') WHERE v.build_id=p_build AND v.frozen_digest=p_frozen AND v.passed ON CONFLICT DO NOTHING;
 RETURN QUERY SELECT * FROM ops.pdf_build_validation WHERE build_id=p_build AND frozen_digest=p_frozen AND contract_digest=contract_;
END $$;
CREATE OR REPLACE FUNCTION ops.seal_pdf_build(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text,p_key text)
RETURNS SETOF ops.pdf_published_revision LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build; v ops.pdf_build_validation; prior ops.pdf_published_revision; kind_ text;
BEGIN
 PERFORM ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 SELECT * INTO prior FROM ops.pdf_published_revision WHERE build_id=p_build;
 IF FOUND THEN IF prior.product_key IS DISTINCT FROM p_key THEN RAISE EXCEPTION 'published key replay differs'; END IF; RETURN NEXT prior; RETURN; END IF;
 PERFORM sem.require_execution_operation(b.release_id,'seal_pdf_build');
 SELECT * INTO STRICT v FROM ops.pdf_build_validation WHERE build_id=p_build AND frozen_digest=p_frozen AND native_callbacks;
 IF p_key IS NULL OR p_key='' THEN RAISE EXCEPTION 'empty PDF product key'; END IF;
 SELECT kind INTO STRICT kind_ FROM ops.pdf_frozen_build WHERE build_id=p_build;
 IF kind_='integrated' AND (NOT EXISTS(SELECT FROM kb.pdf_record_companion WHERE product_id=p_build AND family='input')
 OR NOT EXISTS(SELECT FROM kb.pdf_record_companion WHERE product_id=p_build AND family='coverage')) THEN
 RAISE EXCEPTION 'integrated publication lacks input/coverage inventory' USING ERRCODE='23514'; END IF;
 INSERT INTO ops.pdf_product(task_id,product_key,content_digest,kind,artifact_digest,release_id,contract_digest)
 VALUES(p_task,p_key,v.logical_digest,kind_,b.source_digest,b.release_id,v.contract_digest);
 INSERT INTO ops.pdf_product_input(task_id,product_key,input_index,role,input_task_id,input_product_key,input_content_digest)
 SELECT p_task,p_key,c.local_id::bigint,c.body->>'role',(c.body->>'task_id')::bigint,c.body->>'product_key',c.body->>'content_digest'
 FROM kb.pdf_record_companion c WHERE c.product_id=p_build AND c.family='input';
 INSERT INTO kb.source_artifact(artifact_digest,content)
 SELECT b.schema_digest,content FROM sem.input WHERE release_id=b.release_id AND input_kind='dependency'
 AND input_name='execution/implementation/pdf/docling-validation.schema.json' AND encode(sha256(content),'hex')=b.schema_digest
 ON CONFLICT DO NOTHING;
 INSERT INTO ops.pdf_product_artifact(task_id,product_key,artifact_digest)
 SELECT p_task,p_key,a.artifact_digest FROM kb.source_artifact a
 WHERE a.artifact_digest IN (b.source_digest,b.schema_digest,b.recipe_digest);
 INSERT INTO ops.pdf_published_revision VALUES(p_build,p_task,p_key,v.logical_digest,b.release_id,b.source_digest,b.schema_digest,b.recipe_digest,p_frozen,kind_)
 RETURNING * INTO prior;
 UPDATE ops.pdf_stage_build SET state='published' WHERE build_id=p_build;
 RETURN NEXT prior;
END $$;

CREATE OR REPLACE FUNCTION ops.read_pdf_record_rows(p_task bigint,p_product text,p_digest text,
 p_family text,p_filters jsonb,p_after jsonb,p_limit integer)
RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $reader$
DECLARE published ops.pdf_published_revision;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 OR p_filters IS NULL OR
 jsonb_typeof(p_filters)<>'object' OR (p_after IS NOT NULL AND jsonb_typeof(p_after)<>'array') THEN
 RAISE EXCEPTION 'invalid published record page' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT published FROM ops.read_pdf_published_revision(p_task,p_product,p_digest);
 CASE p_family
WHEN 'header' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY[]::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.product_id)) FROM ops.pdf_record_document r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND (true) AND (p_after IS NULL OR ROW(r.product_id)>ROW((p_after->>0)))
 ORDER BY r.product_id LIMIT p_limit;
WHEN 'native' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['record_id','native_address']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.record_id)) FROM kb.pdf_record_native r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'record_id' OR r.record_id=p_filters->>'record_id') AND (NOT p_filters ? 'native_address' OR r.native_address=p_filters->>'native_address')) AND (p_after IS NULL OR ROW(r.record_id)>ROW((p_after->>0)))
 ORDER BY r.record_id LIMIT p_limit;
WHEN 'membership' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['parent_id','field_name']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.parent_id,r.field_name,r.ordinal)) FROM kb.pdf_record_membership r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'parent_id' OR r.parent_id=p_filters->>'parent_id') AND (NOT p_filters ? 'field_name' OR r.field_name=p_filters->>'field_name')) AND (p_after IS NULL OR ROW(r.parent_id,r.field_name,r.ordinal)>ROW((p_after->>0),(p_after->>1),(p_after->>2)::bigint))
 ORDER BY r.parent_id,r.field_name,r.ordinal NULLS LAST LIMIT p_limit;
WHEN 'reference' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['source_id','target_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.reference_id)) FROM kb.pdf_record_reference r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'source_id' OR r.source_id=p_filters->>'source_id') AND (NOT p_filters ? 'target_id' OR r.target_id=p_filters->>'target_id')) AND (p_after IS NULL OR ROW(r.reference_id)>ROW((p_after->>0)))
 ORDER BY r.reference_id LIMIT p_limit;
WHEN 'artifact_stream' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['stream_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.stream_id)) FROM ops.pdf_artifact_stream r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'stream_id' OR r.stream_id=p_filters->>'stream_id')) AND (p_after IS NULL OR ROW(r.stream_id)>ROW((p_after->>0)))
 ORDER BY r.stream_id LIMIT p_limit;
WHEN 'artifact_part' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['stream_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.stream_id,r.ordinal)) FROM ops.pdf_artifact_part r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'stream_id' OR r.stream_id=p_filters->>'stream_id')) AND (p_after IS NULL OR ROW(r.stream_id,r.ordinal)>ROW((p_after->>0),(p_after->>1)::bigint))
 ORDER BY r.stream_id,r.ordinal NULLS LAST LIMIT p_limit;
WHEN 'companion' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['family','local_id','kind','pointer']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.family,r.ordinal,r.local_id))||jsonb_build_object('_fields',COALESCE((SELECT jsonb_agg(jsonb_build_object('field_name',cf.field_name,'stream_id',cf.stream_id,'scalar_kind',cf.scalar_kind) ORDER BY cf.field_name) FROM kb.pdf_record_companion_field cf WHERE cf.product_id=r.product_id AND cf.revision_id=r.revision_id AND cf.family=r.family AND cf.local_id=r.local_id),'[]'::jsonb)) FROM kb.pdf_record_companion r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'family' OR r.family=p_filters->>'family') AND (NOT p_filters ? 'local_id' OR r.local_id=p_filters->>'local_id') AND (NOT p_filters ? 'kind' OR r.body->'kind'=p_filters->'kind') AND (NOT p_filters ? 'pointer' OR r.body->'pointer'=p_filters->'pointer')) AND (p_after IS NULL OR ((p_after->1='null'::jsonb AND (r.family>p_after->>0 OR r.family=p_after->>0 AND r.ordinal IS NULL AND r.local_id>p_after->>2)) OR (p_after->1<>'null'::jsonb AND (ROW(r.family,r.ordinal,r.local_id)>ROW((p_after->>0),(p_after->>1)::bigint,(p_after->>2)) OR r.family=p_after->>0 AND r.ordinal IS NULL))))
 ORDER BY r.family,r.ordinal NULLS LAST,r.local_id LIMIT p_limit;
WHEN 'companion_field' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['family','local_id','field_name']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.family,r.local_id,r.field_name)) FROM kb.pdf_record_companion_field r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'family' OR r.family=p_filters->>'family') AND (NOT p_filters ? 'local_id' OR r.local_id=p_filters->>'local_id') AND (NOT p_filters ? 'field_name' OR r.field_name=p_filters->>'field_name')) AND (p_after IS NULL OR ROW(r.family,r.local_id,r.field_name)>ROW((p_after->>0),(p_after->>1),(p_after->>2)))
 ORDER BY r.family,r.local_id,r.field_name LIMIT p_limit;
WHEN 'endpoint' THEN
 IF EXISTS(SELECT FROM jsonb_object_keys(p_filters) k WHERE NOT k=ANY(ARRAY['relation_id','occurrence_id']::text[])) THEN
 RAISE EXCEPTION 'unsupported published record filter' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT to_jsonb(r)||jsonb_build_object('_cursor',jsonb_build_array(r.relation_id,r.ordinal)) FROM kb.pdf_record_endpoint r
 WHERE r.product_id=published.build_id AND r.revision_id=published.build_id
 AND ((NOT p_filters ? 'relation_id' OR r.relation_id=p_filters->>'relation_id') AND (NOT p_filters ? 'occurrence_id' OR r.occurrence_id=p_filters->>'occurrence_id')) AND (p_after IS NULL OR ROW(r.relation_id,r.ordinal)>ROW((p_after->>0),(p_after->>1)::bigint))
 ORDER BY r.relation_id,r.ordinal NULLS LAST LIMIT p_limit;
 ELSE RAISE EXCEPTION 'unknown published record family' USING ERRCODE='22023';
 END CASE;
END $reader$;
REVOKE ALL ON FUNCTION ops.read_pdf_record_rows(bigint,text,text,text,jsonb,jsonb,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.read_pdf_record_rows(bigint,text,text,text,jsonb,jsonb,integer)
 TO corpus_sem_reader,corpus_sem_writer,corpus_sem_evaluator;

CREATE OR REPLACE FUNCTION ops.read_pdf_record_context_rows(p_task bigint,p_product text,p_digest text,
 p_pointers text[],p_section text,p_family text,p_after text,p_limit integer)
RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $reader$
DECLARE published ops.pdf_published_revision;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 1000 OR p_pointers IS NULL OR
 p_family NOT IN ('occurrence','relation','input','coverage','mapping_report','health') THEN
 RAISE EXCEPTION 'invalid published context page' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT published FROM ops.read_pdf_published_revision(p_task,p_product,p_digest);
 RETURN QUERY WITH selected AS MATERIALIZED (
 SELECT c.* FROM kb.pdf_record_companion c WHERE c.product_id=published.build_id
 AND c.revision_id=published.build_id AND c.family='occurrence' AND c.body->>'pointer'=ANY(p_pointers)
 ), related AS MATERIALIZED (
 SELECT DISTINCT e.relation_id FROM kb.pdf_record_endpoint e JOIN selected c ON c.local_id=e.occurrence_id
 WHERE e.product_id=published.build_id AND e.revision_id=published.build_id
 AND (e.target_task_id=p_task AND e.target_product_key=p_product OR e.target_task_id=0 AND e.target_product_key='@self')
 ), endpoints AS MATERIALIZED (
 SELECT e.* FROM kb.pdf_record_endpoint e JOIN related r USING(relation_id)
 WHERE e.product_id=published.build_id AND e.revision_id=published.build_id
 ), covered AS MATERIALIZED (
 SELECT c.* FROM kb.pdf_record_companion c WHERE c.product_id=published.build_id
 AND c.revision_id=published.build_id AND c.family='coverage' AND (
 c.body->>'scope' IN ('whole_document',p_section||':direct',p_section||':descendants') OR
 c.body->>'scope' IN (SELECT 'page:'||(o.body->>'page_no') FROM selected o UNION ALL
 SELECT 'pages:'||(o.body->>'page_no')||'-'||(o.body->>'page_no') FROM selected o))
 ), inputs AS MATERIALIZED (
 SELECT c.* FROM kb.pdf_record_companion c WHERE c.product_id=published.build_id
 AND c.revision_id=published.build_id AND c.family='input' AND (
 EXISTS(SELECT FROM endpoints e WHERE e.role<>'output'
 AND (e.target_task_id,e.target_product_key,e.target_content_digest)=
 ((c.body->>'task_id')::bigint,c.body->>'product_key',c.body->>'content_digest')) OR
 c.local_id IN (SELECT s->>'input_index' FROM covered x
 CROSS JOIN LATERAL jsonb_array_elements(COALESCE(x.body->'supports','[]')) s))
 ) SELECT jsonb_build_object('local_id',c.local_id,'body',c.body)
 FROM kb.pdf_record_companion c WHERE c.product_id=published.build_id
 AND c.revision_id=published.build_id AND c.family=p_family AND c.local_id>COALESCE(p_after,'')
 AND CASE p_family
 WHEN 'occurrence' THEN c.local_id IN (SELECT local_id FROM selected)
 WHEN 'relation' THEN c.local_id IN (SELECT relation_id FROM endpoints)
 WHEN 'coverage' THEN c.local_id IN (SELECT local_id FROM covered)
 WHEN 'input' THEN c.local_id IN (SELECT local_id FROM inputs)
 WHEN 'mapping_report' THEN c.body->>'input_index' IN (SELECT local_id FROM inputs)
 WHEN 'health' THEN true ELSE false END
 ORDER BY c.local_id LIMIT p_limit;
END $reader$;
REVOKE ALL ON FUNCTION ops.read_pdf_record_context_rows(bigint,text,text,text[],text,text,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.read_pdf_record_context_rows(bigint,text,text,text[],text,text,text,integer)
 TO corpus_sem_reader,corpus_sem_writer,corpus_sem_evaluator;

CREATE OR REPLACE FUNCTION ops.read_pdf_native_events(p_task bigint,p_product text,p_digest text)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $events$
WITH RECURSIVE published AS MATERIALIZED (
 SELECT * FROM ops.read_pdf_published_revision(p_task,p_product,p_digest)
), nodes AS MATERIALIZED (
 SELECT n.* FROM kb.pdf_record_native n JOIN published p ON n.product_id=p.build_id AND n.revision_id=p.build_id
), members AS MATERIALIZED (
 SELECT m.* FROM kb.pdf_record_membership m JOIN published p ON m.product_id=p.build_id AND m.revision_id=p.build_id
), fields AS MATERIALIZED (
 SELECT record_id,name,value,kind,row_number() OVER(PARTITION BY record_id ORDER BY name COLLATE "C")-1 AS slot
 FROM (
 SELECT n.record_id,x.key AS name,x.value,'scalar'::text AS kind FROM nodes n
 CROSS JOIN LATERAL jsonb_each(n.scalars_json) x
 UNION ALL
 SELECT n.record_id,x.key,x.value,x.value->>'kind' FROM nodes n
 CROSS JOIN LATERAL jsonb_each(n.structure_json->'fields') x
 ) f
), edges AS MATERIALIZED (
 SELECT f.record_id AS parent_id,f.value->>'target' AS child_id,ARRAY[1,f.slot,1]::bigint[] AS suffix
 FROM fields f WHERE f.kind='object'
 UNION ALL
 SELECT m.parent_id,m.record_id,ARRAY[1,f.slot,1,1,m.ordinal,1]::bigint[] FROM members m
 JOIN fields f ON f.record_id=m.parent_id AND f.name=m.field_name WHERE m.value_kind='record'
), walk(record_id,path) AS (
 SELECT h.root_id,ARRAY[]::bigint[] FROM ops.pdf_record_document h JOIN published p
 ON h.product_id=p.build_id AND h.revision_id=p.build_id
 UNION ALL
 SELECT e.child_id,w.path||e.suffix FROM walk w JOIN edges e ON e.parent_id=w.record_id
), events(path,kind,value,prefix) AS (
 SELECT w.path||ARRAY[0]::bigint[],'literal',to_jsonb(CASE WHEN n.native_type='NativeArray' THEN '' ELSE '{' END),''
 FROM walk w JOIN nodes n USING(record_id)
 UNION ALL
 SELECT w.path||ARRAY[1,f.slot,0]::bigint[],'literal',to_jsonb(CASE WHEN n.native_type='NativeArray' THEN ''
 ELSE (CASE WHEN f.slot>0 THEN ',' ELSE '' END)||to_jsonb(f.name)::text||':' END),''
 FROM walk w JOIN nodes n USING(record_id) JOIN fields f USING(record_id)
 UNION ALL
 SELECT w.path||ARRAY[1,f.slot,1]::bigint[],CASE WHEN f.kind='scalar' THEN 'inline' ELSE 'parts' END,
 CASE WHEN f.kind='scalar' THEN f.value ELSE to_jsonb(f.value->>'stream_id') END,''
 FROM walk w JOIN fields f USING(record_id) WHERE f.kind IN ('scalar','parts')
 UNION ALL
 SELECT w.path||ARRAY[1,f.slot,1,0]::bigint[],'literal',to_jsonb(CASE WHEN f.kind='map' THEN '{' ELSE '[' END),''
 FROM walk w JOIN fields f USING(record_id) WHERE f.kind IN ('array','map')
 UNION ALL
 SELECT w.path||ARRAY[1,f.slot,1,1,m.ordinal,0]::bigint[],
 CASE WHEN f.kind='map' AND m.member_key IS NULL THEN 'key_parts' ELSE 'literal' END,
 CASE WHEN f.kind='map' AND m.member_key IS NULL THEN to_jsonb(m.member_key_stream_id)
 ELSE to_jsonb((CASE WHEN m.ordinal>0 THEN ',' ELSE '' END)||
 CASE WHEN f.kind='map' THEN to_jsonb(m.member_key)::text||':' ELSE '' END) END,
 CASE WHEN m.ordinal>0 THEN ',' ELSE '' END
 FROM walk w JOIN fields f USING(record_id) JOIN members m ON m.parent_id=f.record_id AND m.field_name=f.name
 WHERE f.kind IN ('array','map')
 UNION ALL
 SELECT w.path||ARRAY[1,f.slot,1,1,m.ordinal,1]::bigint[],
 CASE WHEN m.value_kind='scalar' THEN 'inline' ELSE 'parts' END,
 CASE WHEN m.value_kind='scalar' THEN m.scalar_json ELSE to_jsonb(m.stream_id) END,''
 FROM walk w JOIN fields f USING(record_id) JOIN members m ON m.parent_id=f.record_id AND m.field_name=f.name
 WHERE m.value_kind IN ('scalar','parts')
 UNION ALL
 SELECT w.path||ARRAY[1,f.slot,1,2]::bigint[],'literal',to_jsonb(CASE WHEN f.kind='map' THEN '}' ELSE ']' END),''
 FROM walk w JOIN fields f USING(record_id) WHERE f.kind IN ('array','map')
 UNION ALL
 SELECT w.path||ARRAY[1,(SELECT count(*) FROM fields f WHERE f.record_id=n.record_id),0]::bigint[],
 'extension',n.structure_json->'extensions'->'stream_id',
 CASE WHEN EXISTS(SELECT FROM fields f WHERE f.record_id=n.record_id) THEN ',' ELSE '' END
 FROM walk w JOIN nodes n USING(record_id) WHERE n.structure_json ? 'extensions'
 UNION ALL
 SELECT w.path||ARRAY[2]::bigint[],'literal',to_jsonb(CASE WHEN n.native_type='NativeArray' THEN '' ELSE '}' END),''
 FROM walk w JOIN nodes n USING(record_id)
) SELECT jsonb_build_object('kind',kind,'value',value,'prefix',prefix) FROM events ORDER BY path
$events$;
REVOKE ALL ON FUNCTION ops.read_pdf_native_events(bigint,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.read_pdf_native_events(bigint,text,text)
 TO corpus_sem_reader,corpus_sem_writer,corpus_sem_evaluator;

CREATE OR REPLACE FUNCTION ops.read_pdf_companion_export_events(p_task bigint,p_key text,p_digest text,p_family text)
RETURNS SETOF jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
WITH published AS MATERIALIZED (
 SELECT * FROM ops.read_pdf_published_revision(p_task,p_key,p_digest)
), companions AS MATERIALIZED (
 SELECT c.* FROM kb.pdf_record_companion c JOIN published p ON c.product_id=p.build_id AND c.revision_id=p.build_id
 WHERE c.family=p_family
), fields AS MATERIALIZED (
 SELECT cf.*,c.ordinal AS row_ordinal FROM kb.pdf_record_companion_field cf
 JOIN companions c USING(product_id,revision_id,family,local_id)
), events(ordinal,local_id,phase,field_name,subphase,part_ordinal,event) AS (
 SELECT c.ordinal,c.local_id,0,''::text,0,0::bigint,jsonb_build_object('kind','row','body',c.body) FROM companions c
 UNION ALL
 SELECT f.row_ordinal,f.local_id,1,f.field_name,0,0::bigint,jsonb_build_object('kind','field','field',
 to_jsonb(s)||jsonb_build_object('field_name',f.field_name,'scalar_kind',f.scalar_kind))
 FROM fields f JOIN ops.pdf_artifact_stream s USING(product_id,revision_id,stream_id)
 UNION ALL
 SELECT f.row_ordinal,f.local_id,1,f.field_name,1,part.ordinal,jsonb_build_object('kind','part','part',to_jsonb(part))
 FROM fields f JOIN ops.pdf_artifact_part part USING(product_id,revision_id,stream_id)
 UNION ALL
 SELECT c.ordinal,c.local_id,2,''::text,0,0::bigint,jsonb_build_object('kind','close') FROM companions c
) SELECT event FROM events ORDER BY ordinal,local_id,phase,field_name,subphase,part_ordinal
$$;
REVOKE ALL ON FUNCTION ops.read_pdf_companion_export_events(bigint,text,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.read_pdf_companion_export_events(bigint,text,text,text)
 TO corpus_sem_reader,corpus_sem_writer,corpus_sem_evaluator;

-- One release-bound relational context selection shared by Python and frame guards.
CREATE OR REPLACE FUNCTION ops.pdf_record_context_rows(p_task bigint,p_key text,p_digest text,p_pointers text[],p_section text)
RETURNS TABLE(family text,local_id text,ordinal bigint,body jsonb)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 WITH published AS MATERIALIZED (
  SELECT * FROM ops.read_pdf_published_revision(p_task,p_key,p_digest)
 ), selected AS MATERIALIZED (
  SELECT c.* FROM kb.pdf_record_companion c JOIN published p ON c.product_id=p.build_id AND c.revision_id=p.build_id
  WHERE c.family='occurrence' AND c.body->>'pointer'=ANY(p_pointers)
 ), related AS MATERIALIZED (
  SELECT DISTINCT e.relation_id FROM kb.pdf_record_endpoint e JOIN published p ON e.product_id=p.build_id AND e.revision_id=p.build_id
  JOIN selected c ON c.local_id=e.occurrence_id
  WHERE (e.target_task_id=p_task AND e.target_product_key=p_key AND e.target_content_digest=p_digest)
   OR (e.target_task_id=0 AND e.target_product_key='@self' AND e.target_content_digest='@self')
 ), endpoints AS MATERIALIZED (
  SELECT e.* FROM kb.pdf_record_endpoint e JOIN published p ON e.product_id=p.build_id AND e.revision_id=p.build_id
  JOIN related r USING(relation_id)
 ), covered AS MATERIALIZED (
  SELECT c.* FROM kb.pdf_record_companion c JOIN published p ON c.product_id=p.build_id AND c.revision_id=p.build_id
  WHERE c.family='coverage' AND (c.body->>'scope' IN ('whole_document',p_section||':direct',p_section||':descendants')
   OR c.body->>'scope' IN (SELECT 'page:'||(o.body->>'page_no') FROM selected o UNION ALL
      SELECT 'pages:'||(o.body->>'page_no')||'-'||(o.body->>'page_no') FROM selected o))
 ), inputs AS MATERIALIZED (
  SELECT c.* FROM kb.pdf_record_companion c JOIN published p ON c.product_id=p.build_id AND c.revision_id=p.build_id
  WHERE c.family='input' AND (EXISTS(SELECT FROM endpoints e WHERE e.role<>'output' AND
   (e.target_task_id,e.target_product_key,e.target_content_digest)=
   ((c.body->>'task_id')::bigint,c.body->>'product_key',c.body->>'content_digest')) OR
   c.local_id IN (SELECT support->>'input_index' FROM covered x
    CROSS JOIN LATERAL jsonb_array_elements(COALESCE(x.body->'supports','[]')) support))
 ), chosen AS (
  SELECT * FROM selected UNION ALL SELECT * FROM covered UNION ALL SELECT * FROM inputs
  UNION ALL SELECT c.* FROM kb.pdf_record_companion c JOIN published p ON c.product_id=p.build_id AND c.revision_id=p.build_id
   WHERE c.family='relation' AND c.local_id IN (SELECT relation_id FROM related)
  UNION ALL SELECT c.* FROM kb.pdf_record_companion c JOIN published p ON c.product_id=p.build_id AND c.revision_id=p.build_id
   WHERE c.family='mapping_report' AND c.body->>'input_index' IN (SELECT local_id FROM inputs)
 ) SELECT c.family,c.local_id,c.ordinal,ops.pdf_companion_body(c.product_id,c.revision_id,c.family,c.local_id,c.body) FROM chosen c
$$;

CREATE OR REPLACE FUNCTION ops.record_integrated_source_context(p_task bigint,p_key text,p_digest text,
 p_pointers text[],p_section text,p_membership text,p_row_budget bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE published ops.pdf_published_revision; actual_rows bigint; result_ jsonb;
BEGIN
 IF p_pointers IS NULL OR p_section IS NULL OR p_membership IS NULL OR p_membership NOT IN ('direct','descendants')
 OR (p_row_budget IS NOT NULL AND p_row_budget<1) THEN
 RAISE EXCEPTION 'invalid published source context selector' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT published FROM ops.read_pdf_published_revision(p_task,p_key,p_digest);
 -- Budgeted reads count before materialization. Ordinary section contexts use
 -- one set-shaped pass, without repeated scans for each continuation page.
 IF p_row_budget IS NOT NULL THEN
 SELECT count(*)+COALESCE(sum(CASE WHEN c.family='relation' THEN jsonb_array_length(c.body->'endpoints') ELSE 0 END),0)
 INTO actual_rows FROM ops.pdf_record_context_rows(p_task,p_key,p_digest,p_pointers,p_section) c;
 IF actual_rows>p_row_budget THEN
 RAISE EXCEPTION 'PDF mandatory companion exceeds requested row budget' USING ERRCODE='23514'; END IF;
 END IF;
 WITH chosen AS MATERIALIZED (
  SELECT * FROM ops.pdf_record_context_rows(p_task,p_key,p_digest,p_pointers,p_section)
 ), wrapped AS (
  SELECT c.family,c.ordinal,c.local_id,jsonb_build_object('task_id',p_task,'product_key',p_key)||
  CASE c.family
   WHEN 'input' THEN jsonb_build_object('input_index',c.local_id::bigint,'role',c.body->'role',
    'input_task_id',(c.body->>'task_id')::bigint,'input_product_key',c.body->'product_key','input_content_digest',c.body->'content_digest')
   WHEN 'occurrence' THEN jsonb_build_object('occurrence_id',c.local_id,'pointer',c.body->'pointer','kind',c.body->'kind',
    'precision',c.body->'precision','address_space',c.body->'address_space','body',c.body)
   WHEN 'coverage' THEN jsonb_build_object('coverage_id',c.local_id,'body',c.body)
   WHEN 'mapping_report' THEN jsonb_build_object('report_index',c.local_id::bigint,'input_index',(c.body->>'input_index')::bigint,'body',c.body)
   WHEN 'relation' THEN jsonb_build_object('relation_id',c.local_id,'kind',c.body->'kind','body',c.body-'endpoints',
    'endpoints',COALESCE((SELECT jsonb_agg(jsonb_build_object(
     'task_id',p_task,'product_key',p_key,'relation_id',e.relation_id,'endpoint_index',e.ordinal,'role',e.role,
     'target_task_id',CASE WHEN e.target_task_id=0 THEN p_task ELSE e.target_task_id END,
     'target_product_key',CASE WHEN e.target_task_id=0 THEN p_key ELSE e.target_product_key END,
     'target_content_digest',CASE WHEN e.target_task_id=0 THEN p_digest ELSE e.target_content_digest END,
     'occurrence_id',e.occurrence_id) ORDER BY e.ordinal) FROM kb.pdf_record_endpoint e
     WHERE e.product_id=published.build_id AND e.revision_id=published.build_id AND e.relation_id=c.local_id),'[]'))
   ELSE '{}'::jsonb END AS body FROM chosen c
 ), grouped AS (
  SELECT family,jsonb_agg(body ORDER BY ordinal,local_id) body FROM wrapped GROUP BY family
 ) SELECT jsonb_build_object('selection',jsonb_build_object('task_id',p_task,'product_key',p_key,'content_digest',p_digest),
  'descriptor',jsonb_build_object('version',2,'kind','integrated','revision',to_jsonb(published)),
  'inputs',COALESCE((SELECT body FROM grouped WHERE family='input'),'[]'),
  'occurrences',COALESCE((SELECT body FROM grouped WHERE family='occurrence'),'[]'),
  'relations',COALESCE((SELECT body FROM grouped WHERE family='relation'),'[]'),
  'coverage',COALESCE((SELECT body FROM grouped WHERE family='coverage'),'[]'),
  'mapping_reports',COALESCE((SELECT body FROM grouped WHERE family='mapping_report'),'[]')) INTO result_;
 RETURN result_;
END $$;
REVOKE ALL ON FUNCTION ops.pdf_record_context_rows(bigint,text,text,text[],text),
 ops.record_integrated_source_context(bigint,text,text,text[],text,text,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.record_integrated_source_context(bigint,text,text,text[],text,text,bigint)
 TO corpus_sem_reader,corpus_sem_writer,corpus_sem_evaluator;

CREATE OR REPLACE FUNCTION ops.legacy_integrated_source_context(p_task bigint,p_key text,p_digest text,p_pointers text[],p_section text,p_membership text) RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $context$
 WITH selected AS (
  SELECT o.* FROM kb.pdf_occurrence o WHERE o.task_id=p_task AND o.product_key=p_key AND o.pointer=ANY(p_pointers)
 ), relation_ids AS (
  SELECT DISTINCT e.relation_id FROM kb.pdf_relation_endpoint e JOIN selected o ON o.occurrence_id=e.occurrence_id
  WHERE e.task_id=p_task AND e.product_key=p_key AND e.target_task_id=p_task AND e.target_product_key=p_key
 ), related AS (
  SELECT r.* FROM kb.pdf_relation r JOIN relation_ids i USING(relation_id) WHERE r.task_id=p_task AND r.product_key=p_key
 ), endpoint_rows AS (
  SELECT e.* FROM kb.pdf_relation_endpoint e JOIN relation_ids i USING(relation_id) WHERE e.task_id=p_task AND e.product_key=p_key
 ), covered AS (
  SELECT c.* FROM kb.pdf_product_coverage c WHERE c.task_id=p_task AND c.product_key=p_key AND (
   c.body->>'scope' IN ('whole_document',p_section||':direct',p_section||':descendants') OR
   c.body->>'scope' IN (SELECT 'page:'||(o.body->>'page_no') FROM selected o UNION ALL SELECT 'pages:'||(o.body->>'page_no')||'-'||(o.body->>'page_no') FROM selected o)
  )
 ), input_rows AS (
  SELECT i.* FROM ops.pdf_product_input i WHERE i.task_id=p_task AND i.product_key=p_key AND (
   EXISTS(SELECT FROM endpoint_rows e WHERE e.role<>'output' AND (e.target_task_id,e.target_product_key,e.target_content_digest)=(i.input_task_id,i.input_product_key,i.input_content_digest)) OR
   i.input_index IN (SELECT (s->>'input_index')::bigint FROM covered c CROSS JOIN LATERAL jsonb_array_elements(COALESCE(c.body->'supports','[]')) s)
  )
 ) SELECT jsonb_build_object(
  'selection',jsonb_build_object('task_id',p.task_id,'product_key',p.product_key,'content_digest',p.content_digest),
  'descriptor',b.descriptor,
  'occurrences',COALESCE((SELECT jsonb_agg(to_jsonb(o) ORDER BY o.occurrence_id) FROM selected o),'[]'),
  'relations',COALESCE((SELECT jsonb_agg((to_jsonb(r)-'body')||jsonb_build_object('body',r.body-'endpoints','endpoints',COALESCE((SELECT jsonb_agg(to_jsonb(e) ORDER BY e.endpoint_index) FROM endpoint_rows e WHERE e.relation_id=r.relation_id),'[]')) ORDER BY r.relation_id) FROM related r),'[]'),
  'coverage',COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.coverage_id) FROM covered c),'[]'),
  'mapping_reports',COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.report_index) FROM kb.pdf_mapping_report m WHERE m.task_id=p_task AND m.product_key=p_key AND m.input_index IN (SELECT input_index FROM input_rows)),'[]'),
  'inputs',COALESCE((SELECT jsonb_agg(to_jsonb(i) ORDER BY i.input_index) FROM input_rows i),'[]')
 ) FROM ops.pdf_product p JOIN ops.pdf_product_body b USING(task_id,product_key)
 WHERE p.task_id=p_task AND p.product_key=p_key AND p.content_digest=p_digest AND p.kind='integrated'
$context$;
REVOKE ALL ON FUNCTION ops.legacy_integrated_source_context(bigint,text,text,text[],text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.legacy_integrated_source_context(bigint,text,text,text[],text,text) TO corpus_sem_writer,corpus_sem_reader;

CREATE OR REPLACE FUNCTION ops.integrated_source_context(p_task bigint,p_key text,p_digest text,p_pointers text[],p_section text,p_membership text)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 IF EXISTS(SELECT FROM ops.pdf_published_revision WHERE task_id=p_task AND product_key=p_key AND logical_digest=p_digest) THEN
 RETURN ops.record_integrated_source_context(p_task,p_key,p_digest,p_pointers,p_section,p_membership);
 END IF;
 RETURN ops.legacy_integrated_source_context(p_task,p_key,p_digest,p_pointers,p_section,p_membership);
END $$;
REVOKE ALL ON FUNCTION ops.integrated_source_context(bigint,text,text,text[],text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION ops.integrated_source_context(bigint,text,text,text[],text,text) TO corpus_sem_writer,corpus_sem_reader;
CREATE OR REPLACE VIEW ops.pdf_published_item AS SELECT * FROM kb.native_document_item UNION ALL SELECT p.task_id,p.product_key,r.pointer,r.ordinal,r.label,r.parent_pointer,r.section_pointer,r.content_layer,r.text,r.native_json FROM kb.pdf_record_access r JOIN ops.pdf_published_revision p ON r.product_id=p.build_id;
ALTER VIEW ops.pdf_published_item OWNER TO corpus_sem_publisher; GRANT SELECT ON ops.pdf_published_item TO corpus_sem_writer,corpus_sem_reader,corpus_sem_evaluator;
CREATE OR REPLACE VIEW ops.pdf_published_region AS SELECT * FROM kb.native_document_region UNION ALL SELECT p.task_id,p.product_key,r.pointer,r.region_index,r.page_no,r.page_width,r.page_height,r.left,r.top,r.right,r.bottom,r.origin FROM kb.pdf_record_region r JOIN ops.pdf_published_revision p ON r.product_id=p.build_id;
ALTER VIEW ops.pdf_published_region OWNER TO corpus_sem_publisher; GRANT SELECT ON ops.pdf_published_region TO corpus_sem_writer,corpus_sem_reader,corpus_sem_evaluator;
CREATE OR REPLACE VIEW ops.pdf_selected_product AS
 SELECT task_id,product_key,content_digest,release_id,contract_digest,schema_digest,recipe_digest,parent_task_id,parent_product_key,parent_digest,native_json,health,payload FROM ops.native_document_product
 UNION ALL SELECT p.task_id,p.product_key,p.content_digest,p.release_id,p.contract_digest,
 body.descriptor->'content_metadata'->>'schema_digest',body.descriptor->'content_metadata'->>'recipe_digest',NULL::bigint,NULL::text,NULL::text,
 b.content->'document',body.descriptor->'content_metadata'->'health',body.payload FROM ops.pdf_product p JOIN ops.pdf_product_body body USING(task_id,product_key)
 CROSS JOIN LATERAL (SELECT (convert_from(body.payload,'UTF8')::json->'content')::jsonb content) b WHERE p.kind='integrated'
 UNION ALL SELECT p.task_id,p.product_key,p.logical_digest,p.release_id,v.contract_digest,p.schema_digest,p.recipe_digest,
 NULL::bigint,NULL::text,NULL::text,NULL::jsonb,(SELECT c.body-ARRAY['source_scope','page_start','page_end'] FROM kb.pdf_record_companion c WHERE c.product_id=p.build_id AND c.family='health' AND c.body ? 'source_scope' ORDER BY c.ordinal,c.local_id LIMIT 1),NULL::bytea
 FROM ops.pdf_published_revision p JOIN ops.pdf_build_validation v ON v.build_id=p.build_id;
ALTER VIEW ops.pdf_selected_product OWNER TO corpus_sem_publisher;
GRANT SELECT ON ops.pdf_selected_product TO corpus_sem_writer,corpus_sem_reader,corpus_sem_evaluator,corpus_sem_admitter;

CREATE OR REPLACE FUNCTION ops.lookup_pdf_build(p_task bigint,p_attempt bigint,p_holder text,p_key text)
RETURNS SETOF ops.pdf_stage_build LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE run_ ops.run;
BEGIN
 run_:=ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 PERFORM sem.require_execution_operation(run_.release_id,'inspect_pdf_build');
 RETURN QUERY SELECT * FROM ops.pdf_stage_build WHERE task_id=p_task AND replay_key=p_key AND release_id=run_.release_id;
END $$;
CREATE OR REPLACE FUNCTION ops.lookup_pdf_frozen_digest(p_build text,p_task bigint,p_attempt bigint,p_holder text)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE value_ text;
BEGIN
 PERFORM ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_build WHERE build_id=p_build AND task_id=p_task) THEN RAISE EXCEPTION 'build outside task'; END IF;
 SELECT frozen_digest INTO value_ FROM ops.pdf_frozen_build WHERE build_id=p_build;
 RETURN value_;
END $$;
CREATE OR REPLACE FUNCTION ops.lookup_pdf_frozen_kind(p_build text,p_task bigint,p_attempt bigint,p_holder text)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE value_ text;
BEGIN
 PERFORM ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 IF NOT EXISTS(SELECT FROM ops.pdf_stage_build WHERE build_id=p_build AND task_id=p_task) THEN RAISE EXCEPTION 'build outside task'; END IF;
 SELECT kind INTO value_ FROM ops.pdf_frozen_build WHERE build_id=p_build;
 RETURN value_;
END $$;
CREATE OR REPLACE FUNCTION ops.lookup_pdf_validation(p_build text,p_task bigint,p_attempt bigint,p_holder text,p_frozen text)
RETURNS SETOF ops.pdf_build_validation LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
DECLARE b ops.pdf_stage_build;
BEGIN
 b:=ops.require_pdf_frozen(p_build,p_task,p_attempt,p_holder,p_frozen);
 RETURN QUERY SELECT v.* FROM ops.pdf_build_validation v JOIN sem.input i ON i.release_id=b.release_id
 AND i.input_kind='dependency' AND i.input_name='execution/implementation/pdf/publication.py'
 AND v.native_contract_digest=encode(sha256(i.content),'hex') WHERE v.build_id=p_build AND v.frozen_digest=p_frozen;
END $$;
CREATE OR REPLACE FUNCTION ops.lookup_pdf_published_build(p_build text,p_task bigint,p_attempt bigint,p_holder text)
RETURNS SETOF ops.pdf_published_revision LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
BEGIN
 PERFORM ops.require_pdf_stage_owner(p_task,p_attempt,p_holder);
 RETURN QUERY SELECT * FROM ops.pdf_published_revision WHERE build_id=p_build AND task_id=p_task;
END $$;

CREATE OR REPLACE VIEW ops.pdf_published_coverage AS
 WITH coverage_ AS MATERIALIZED (
 SELECT p.task_id,p.product_key,(ops.pdf_companion_body(c.product_id,c.revision_id,c.family,c.local_id,c.body))->'value' value
 FROM kb.pdf_record_companion c JOIN ops.pdf_published_revision p ON p.build_id=c.product_id
 WHERE c.family='native_metadata' AND c.body->>'kind'='recognition_coverage')
 SELECT * FROM kb.native_document_coverage
 UNION ALL SELECT task_id,product_key,value->>'section_pointer',value->>'membership',value->>'universe',value->>'outcome',value->>'policy' FROM coverage_;
ALTER VIEW ops.pdf_published_coverage OWNER TO corpus_sem_publisher;
GRANT SELECT ON ops.pdf_published_coverage TO corpus_sem_writer,corpus_sem_reader,corpus_sem_evaluator;
CREATE OR REPLACE FUNCTION ops.pdf_record_scope_health(p_task bigint,p_key text,p_digest text,p_pointers text[])
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$
 SELECT (h.body-ARRAY['source_scope','page_start','page_end','formula_outcomes'])||jsonb_build_object('formula_outcomes',
 COALESCE((SELECT jsonb_agg(jsonb_build_object('pointer',c.body->'pointer','outcome',c.body->'outcome')||CASE WHEN c.body->'has_diagnostic'='true'::jsonb THEN jsonb_build_object('diagnostic_ref',jsonb_build_object('task_id',p.task_id,'product_key',p.product_key,'content_digest',p.logical_digest,'family','native_metadata','local_id',c.local_id)) ELSE '{}'::jsonb END ORDER BY c.ordinal,c.local_id) FROM kb.pdf_record_companion c WHERE c.product_id=p.build_id
 AND c.family='native_metadata' AND c.body->>'kind'='formula_outcomes' AND c.body->>'pointer'=ANY(p_pointers)),'[]'::jsonb))
 FROM ops.pdf_published_revision p JOIN kb.pdf_record_companion h ON h.product_id=p.build_id AND h.family='health'
 AND h.body ? 'source_scope' WHERE p.task_id=p_task AND p.product_key=p_key AND p.logical_digest=p_digest
$$;
